import{_ as d,o as r,c as a,ag as l}from"./chunks/framework.Vng7Hdlh.js";const u=JSON.parse('{"title":"操作手册","description":"","frontmatter":{},"headers":[],"relativePath":"manual.md","filePath":"manual.md"}'),o={name:"manual.md"};function e(i,t,h,n,s,b){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="操作手册" tabindex="-1">操作手册 <a class="header-anchor" href="#操作手册" aria-label="Permalink to &quot;操作手册&quot;">​</a></h1><blockquote><p>本文档对应 <strong>微诺管理系统</strong> 后台操作指南。</p></blockquote><hr><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ul><li><a href="#首页">首页</a></li><li><a href="#小程序管理">小程序管理</a></li><li><a href="#小程序页面装修">小程序页面装修</a></li><li><a href="#商户管理">商户管理</a></li><li><a href="#商品券管理">商品券管理</a></li><li><a href="#会员停车管理">会员停车管理</a></li><li><a href="#会员中心">会员中心</a></li><li><a href="#会员营销活动">会员营销活动</a></li><li><a href="#订单中心">订单中心</a></li><li><a href="#公域管理">公域管理</a></li><li><a href="#智慧营销">智慧营销</a></li><li><a href="#bi商业分析">BI商业分析</a></li><li><a href="#门店核销">门店核销</a></li><li><a href="#圈店流程">圈店流程</a></li></ul><hr><h2 id="首页" tabindex="-1">首页 <a class="header-anchor" href="#首页" aria-label="Permalink to &quot;首页&quot;">​</a></h2><p>登录后台后进入首页总览，可快速查看核心数据指标与常用功能入口。</p><h3 id="快速进入" tabindex="-1">快速进入 <a class="header-anchor" href="#快速进入" aria-label="Permalink to &quot;快速进入&quot;">​</a></h3><p>首页顶部提供 9 个快捷入口，点击可直接跳转对应功能模块：</p><table tabindex="0"><thead><tr><th>入口</th><th>说明</th></tr></thead><tbody><tr><td>会员列表</td><td>查看与管理所有会员信息</td></tr><tr><td>商品券</td><td>进入商品券管理页面</td></tr><tr><td>停车券</td><td>进入停车券管理页面</td></tr><tr><td>订单列表</td><td>查看所有交易订单</td></tr><tr><td>核销列表</td><td>查看券码核销记录</td></tr><tr><td>支付即积分</td><td>支付积分规则配置</td></tr><tr><td>停车支付订单</td><td>停车缴费订单查询</td></tr><tr><td>BI 标准版</td><td>进入商业数据分析平台</td></tr><tr><td>系统配置说明</td><td>查看系统配置相关文档</td></tr></tbody></table><h3 id="数据简报" tabindex="-1">数据简报 <a class="header-anchor" href="#数据简报" aria-label="Permalink to &quot;数据简报&quot;">​</a></h3><p>展示当月核心经营数据（实时更新）：</p><table tabindex="0"><thead><tr><th>指标</th><th>说明</th></tr></thead><tbody><tr><td>本月新增会员</td><td>当月新注册会员数量</td></tr><tr><td>总会员数</td><td>累计注册会员总数</td></tr><tr><td>总成交金额（本月）</td><td>当月全部交易金额合计</td></tr><tr><td>总交易笔数（本月）</td><td>当月交易订单总笔数</td></tr></tbody></table><h3 id="系统公告" tabindex="-1">系统公告 <a class="header-anchor" href="#系统公告" aria-label="Permalink to &quot;系统公告&quot;">​</a></h3><p>展示平台重要通知与更新公告，点击「查看更多」可查看历史公告列表。</p><h3 id="数据图表" tabindex="-1">数据图表 <a class="header-anchor" href="#数据图表" aria-label="Permalink to &quot;数据图表&quot;">​</a></h3><p>首页下方提供多维数据可视化看板：</p><ul><li><strong>商场每月销售统计</strong>：月度销售额趋势柱状图</li><li><strong>商场每月业态统计</strong>：各业态销售占比堆叠图</li><li><strong>业态消费统计（当月）</strong>：当月各业态消费占比玫瑰图</li><li><strong>会员数据板块</strong>：会员分层漏斗图（忠诚会员 / 高粘性会员 / 摇摆会员 / 沉睡会员），点击可跳转到 BI 标准版查看 RFM 详细数据</li><li><strong>会员消费排名（当月）</strong>：当月会员消费金额 TOP 排行</li><li><strong>门店销售排行（当月）</strong>：当月门店销售额 TOP 排行</li></ul><hr><h2 id="小程序管理" tabindex="-1">小程序管理 <a class="header-anchor" href="#小程序管理" aria-label="Permalink to &quot;小程序管理&quot;">​</a></h2><h3 id="小程序列表" tabindex="-1">小程序列表 <a class="header-anchor" href="#小程序列表" aria-label="Permalink to &quot;小程序列表&quot;">​</a></h3><h4 id="新增小程序" tabindex="-1">新增小程序 <a class="header-anchor" href="#新增小程序" aria-label="Permalink to &quot;新增小程序&quot;">​</a></h4><ol><li>进入「小程序管理 → 小程序列表」，点击「添加小程序」</li><li>在弹窗中填写以下信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>小程序名称</td><td>✓</td><td>小程序的显示名称</td></tr><tr><td>归属商户</td><td>✓</td><td>选择该小程序归属的商户</td></tr><tr><td>小程序 appid</td><td>✓</td><td>微信小程序的 appid</td></tr><tr><td>小程序 secret</td><td>✓</td><td>微信小程序的 secret</td></tr><tr><td>微信商户号</td><td>—</td><td>微信支付商户号</td></tr><tr><td>每日停车减免</td><td>—</td><td>每日停车减免额度配置</td></tr><tr><td>停车收费商户号</td><td>—</td><td>停车收费对应的商户号</td></tr><tr><td>导航栏颜色</td><td>—</td><td>小程序顶部导航栏颜色</td></tr><tr><td>注册赠送积分</td><td>—</td><td>新会员注册时赠送的积分数量</td></tr><tr><td>微信会员卡 id</td><td>—</td><td>微信会员卡模板 id</td></tr><tr><td>支付宝 appid</td><td>—</td><td>支付宝小程序 appid</td></tr><tr><td>支付宝会员卡模板 id</td><td>—</td><td>支付宝会员卡模板 id</td></tr><tr><td>支付宝授权 Token</td><td>—</td><td>支付宝授权令牌</td></tr><tr><td>支付宝 aes 秘钥</td><td>—</td><td>支付宝加密秘钥</td></tr><tr><td>美团智慧商圈 ID</td><td>—</td><td>美团平台商圈 ID</td></tr><tr><td>经纬度</td><td>—</td><td>商圈地理位置，点击地图按钮选择</td></tr><tr><td>首页底部广告图</td><td>—</td><td>上传图片，≤2MB，png/jpg/jpeg，建议尺寸 212×750</td></tr><tr><td>小程序启动图片</td><td>—</td><td>上传图片，≤2MB，png/jpg/jpeg，建议尺寸 1080×1920</td></tr></tbody></table><ol start="3"><li>确认信息无误后，点击「确定」保存</li></ol><h4 id="列表查询与管理" tabindex="-1">列表查询与管理 <a class="header-anchor" href="#列表查询与管理" aria-label="Permalink to &quot;列表查询与管理&quot;">​</a></h4><ol><li>进入「小程序管理 → 小程序列表」，展示所有已创建的小程序</li><li><strong>搜索筛选</strong>：支持按「小程序名称」和「小程序 appid」模糊搜索，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选左侧复选框，可进行批量修改、删除、更新缓存</li></ol><h4 id="单行操作说明" tabindex="-1">单行操作说明 <a class="header-anchor" href="#单行操作说明" aria-label="Permalink to &quot;单行操作说明&quot;">​</a></h4><p>在列表右侧「操作」列，可对单条小程序执行以下操作：</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>修改</td><td>打开编辑弹窗，修改小程序配置信息</td></tr><tr><td>删除</td><td>删除该小程序（谨慎操作）</td></tr><tr><td>上传支付宝版本</td><td>上传支付宝小程序代码包</td></tr><tr><td>提审支付宝版本</td><td>提交支付宝小程序审核</td></tr><tr><td>积分清零</td><td>清空该小程序下所有会员积分（谨慎操作）</td></tr></tbody></table><p>列表支持分页展示，默认每页 10 条，可切换分页查看。</p><h3 id="首页活动" tabindex="-1">首页活动 <a class="header-anchor" href="#首页活动" aria-label="Permalink to &quot;首页活动&quot;">​</a></h3><p>首页活动用于控制小程序首页各个板块的展示内容，不同的活动类型对应小程序不同的功能入口。</p><h4 id="添加活动" tabindex="-1">添加活动 <a class="header-anchor" href="#添加活动" aria-label="Permalink to &quot;添加活动&quot;">​</a></h4><ol><li>进入「小程序管理 → 首页活动」，点击「添加普通活动」</li><li>在弹窗中填写以下信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>活动标题</td><td>✓</td><td>活动的显示名称</td></tr><tr><td>小程序</td><td>✓</td><td>选择该活动归属的小程序</td></tr><tr><td>显示类型</td><td>✓</td><td>选择活动对应的板块类型（见下表）</td></tr><tr><td>状态</td><td>✓</td><td>启用 / 禁用，默认禁用</td></tr><tr><td>商品显示数量</td><td>✓</td><td>该板块展示的商品数量</td></tr><tr><td>显示顺序</td><td>✓</td><td>数字越小越靠前</td></tr><tr><td>活动开始日期</td><td>—</td><td>活动生效日期</td></tr><tr><td>活动起始时间</td><td>—</td><td>每天的开始展示时间</td></tr><tr><td>活动结束日期</td><td>—</td><td>活动失效日期</td></tr><tr><td>活动结束时间</td><td>—</td><td>每天的结束展示时间</td></tr><tr><td>可用星期</td><td>—</td><td>勾选该活动在星期几展示</td></tr><tr><td>图片</td><td>—</td><td>上传活动展示图，≤2MB，png/jpg/jpeg</td></tr></tbody></table><p><strong>显示类型与建议图片尺寸对照：</strong></p><table tabindex="0"><thead><tr><th>显示类型</th><th>说明</th><th>建议图片尺寸</th></tr></thead><tbody><tr><td>悦品推荐</td><td>首页推荐商品板块</td><td>—</td></tr><tr><td>积分兑好礼</td><td>积分兑换入口</td><td>—</td></tr><tr><td>会员停车</td><td>停车服务入口</td><td>238×300</td></tr><tr><td>生日福袋</td><td>生日福利板块</td><td>686×158</td></tr><tr><td>普通活动</td><td>常规活动展示</td><td>—</td></tr><tr><td>banner活动</td><td>首页轮播 banner</td><td>—</td></tr><tr><td>限时秒杀</td><td>秒杀活动入口</td><td>—</td></tr><tr><td>会员日</td><td>会员专属活动</td><td>—</td></tr><tr><td>新人有礼</td><td>新用户福利入口</td><td>140×140</td></tr></tbody></table><ol start="3"><li>确认信息无误后，点击「确定」保存</li></ol><h4 id="活动管理" tabindex="-1">活动管理 <a class="header-anchor" href="#活动管理" aria-label="Permalink to &quot;活动管理&quot;">​</a></h4><ul><li>列表展示所有已创建的活动，可查看活动名称、显示类型、状态、显示数量等信息</li><li>支持按条件筛选和搜索</li><li>可对活动进行编辑、删除、启用/禁用操作</li></ul><h3 id="小程序菜单" tabindex="-1">小程序菜单 <a class="header-anchor" href="#小程序菜单" aria-label="Permalink to &quot;小程序菜单&quot;">​</a></h3><p>用于配置小程序底部导航菜单的展示内容、顺序、图标及跳转目标。</p><h4 id="添加菜单" tabindex="-1">添加菜单 <a class="header-anchor" href="#添加菜单" aria-label="Permalink to &quot;添加菜单&quot;">​</a></h4><ol><li>进入「小程序管理 → 小程序菜单」，点击「新增」</li><li>在弹窗中填写以下信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>✓</td><td>菜单显示名称，如「首页」「我的」</td></tr><tr><td>小程序</td><td>✓</td><td>选择该菜单归属的小程序</td></tr><tr><td>显示顺序</td><td>—</td><td>数字越小越靠前，控制菜单排列顺序</td></tr><tr><td>菜单标识</td><td>—</td><td>选择菜单对应的页面标识，如首页、品牌导航、个人中心、订单</td></tr><tr><td>菜单颜色</td><td>—</td><td>选择菜单文字颜色样式</td></tr><tr><td>状态</td><td>✓</td><td>启用 / 禁用</td></tr><tr><td>选中状态菜单图标</td><td>—</td><td>菜单被选中时展示的图片，≤2MB，png/jpg/jpeg，建议尺寸 50×50</td></tr><tr><td>未选中状态菜单图标</td><td>—</td><td>菜单未选中时展示的图片，≤2MB，png/jpg/jpeg，建议尺寸 50×50</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="菜单管理" tabindex="-1">菜单管理 <a class="header-anchor" href="#菜单管理" aria-label="Permalink to &quot;菜单管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「小程序」和「状态」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除菜单</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑菜单信息</li><li><strong>删除</strong>：删除该菜单</li></ul></li><li>列表展示已配置的菜单名称、小程序、显示顺序、菜单标识、颜色、状态及图标预览</li></ul><h3 id="轮播图" tabindex="-1">轮播图 <a class="header-anchor" href="#轮播图" aria-label="Permalink to &quot;轮播图&quot;">​</a></h3><p>用于配置小程序首页的轮播 banner，支持设置跳转链接、展示顺序及上下线状态。</p><h4 id="添加轮播图" tabindex="-1">添加轮播图 <a class="header-anchor" href="#添加轮播图" aria-label="Permalink to &quot;添加轮播图&quot;">​</a></h4><ol><li>进入「小程序管理 → 轮播图」，点击「新增」</li><li>在弹窗中填写以下信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>✓</td><td>轮播图名称，用于后台识别</td></tr><tr><td>小程序</td><td>✓</td><td>选择该轮播图归属的小程序</td></tr><tr><td>状态</td><td>✓</td><td>启用 / 禁用</td></tr><tr><td>跳转类型</td><td>—</td><td>内部跳转 / 网页跳转 / 小程序跳转</td></tr><tr><td>显示顺序</td><td>—</td><td>数字越小越靠前</td></tr><tr><td>跳转地址</td><td>—</td><td>根据跳转类型填写对应的页面路径或链接</td></tr><tr><td>图片</td><td>—</td><td>上传轮播展示图，≤2MB，png/jpg/jpeg，建议尺寸 786×1016</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="轮播图管理" tabindex="-1">轮播图管理 <a class="header-anchor" href="#轮播图管理" aria-label="Permalink to &quot;轮播图管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「小程序」和「状态」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除轮播图</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑轮播图信息</li><li><strong>删除</strong>：删除该轮播图</li></ul></li><li>列表展示名称、小程序、类型（微信轮播图）、跳转类型、跳转地址、状态、排序及图片预览</li></ul><h3 id="九宫格" tabindex="-1">九宫格 <a class="header-anchor" href="#九宫格" aria-label="Permalink to &quot;九宫格&quot;">​</a></h3><p>用于配置小程序首页九宫格功能入口的展示图标、名称及跳转目标。</p><h4 id="添加九宫格" tabindex="-1">添加九宫格 <a class="header-anchor" href="#添加九宫格" aria-label="Permalink to &quot;添加九宫格&quot;">​</a></h4><ol><li>进入「小程序管理 → 九宫格」，点击「新增」</li><li>在弹窗中填写以下信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>✓</td><td>九宫格入口显示名称，如「自助积分」「停车缴费」</td></tr><tr><td>小程序</td><td>✓</td><td>选择该入口归属的小程序</td></tr><tr><td>状态</td><td>✓</td><td>启用 / 禁用</td></tr><tr><td>跳转类型</td><td>—</td><td>内部跳转 / 网页跳转 / 小程序跳转</td></tr><tr><td>显示顺序</td><td>—</td><td>数字越小越靠前，控制九宫格排列顺序</td></tr><tr><td>跳转地址</td><td>—</td><td>根据跳转类型填写对应的页面路径或外部链接</td></tr><tr><td>图片</td><td>—</td><td>上传九宫格图标，≤2MB，png/jpg/jpeg，建议尺寸 50×50</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="九宫格管理" tabindex="-1">九宫格管理 <a class="header-anchor" href="#九宫格管理" aria-label="Permalink to &quot;九宫格管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「小程序」和「状态」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除九宫格入口</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑九宫格信息</li><li><strong>删除</strong>：删除该入口</li></ul></li><li>列表展示名称、小程序、类型（微信九宫格）、跳转类型、跳转地址、状态、排序及图标预览</li></ul><h3 id="积分规则图配置" tabindex="-1">积分规则图配置 <a class="header-anchor" href="#积分规则图配置" aria-label="Permalink to &quot;积分规则图配置&quot;">​</a></h3><p>用于配置小程序内会员权益说明、积分规则等展示图片，用户可在小程序个人中心或相关页面查看。</p><h4 id="添加规则图" tabindex="-1">添加规则图 <a class="header-anchor" href="#添加规则图" aria-label="Permalink to &quot;添加规则图&quot;">​</a></h4><ol><li>进入「小程序管理 → 积分规则图配置」，点击「新增」</li><li>在弹窗中填写以下信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>✓</td><td>规则图名称，如「会员权益说明图片」「会员积分规则」</td></tr><tr><td>小程序</td><td>✓</td><td>选择该规则图归属的小程序</td></tr><tr><td>图片</td><td>—</td><td>上传规则展示图，≤2MB，png/jpg/jpeg，建议尺寸 750×高不限</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="规则图管理" tabindex="-1">规则图管理 <a class="header-anchor" href="#规则图管理" aria-label="Permalink to &quot;规则图管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「小程序」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除规则图</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑规则图信息</li><li><strong>删除</strong>：删除该规则图</li></ul></li><li>列表展示主键、名称及图片预览</li></ul><hr><h2 id="小程序页面装修" tabindex="-1">小程序页面装修 <a class="header-anchor" href="#小程序页面装修" aria-label="Permalink to &quot;小程序页面装修&quot;">​</a></h2><h3 id="首页-banner" tabindex="-1">首页 banner <a class="header-anchor" href="#首页-banner" aria-label="Permalink to &quot;首页 banner&quot;">​</a></h3><p>用于配置小程序首页顶部长形 banner 的展示内容，与「小程序管理 → 轮播图」为不同模块，此处为页面装修层面的 banner 配置。</p><h4 id="添加-banner" tabindex="-1">添加 banner <a class="header-anchor" href="#添加-banner" aria-label="Permalink to &quot;添加 banner&quot;">​</a></h4><ol><li>进入「小程序页面装修 → 首页 banner」，点击「新增」</li><li>在弹窗中填写以下信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>✓</td><td>banner 名称，用于后台识别</td></tr><tr><td>小程序</td><td>✓</td><td>选择该 banner 归属的小程序</td></tr><tr><td>状态</td><td>✓</td><td>启用 / 禁用</td></tr><tr><td>跳转类型</td><td>—</td><td>内部跳转 / 网页跳转 / 小程序跳转</td></tr><tr><td>显示顺序</td><td>—</td><td>数字越小越靠前</td></tr><tr><td>跳转地址</td><td>—</td><td>根据跳转类型填写对应的页面路径或链接</td></tr><tr><td>图片</td><td>—</td><td>上传 banner 展示图，≤2MB，png/jpg/jpeg，建议尺寸 1072×372</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="banner-管理" tabindex="-1">banner 管理 <a class="header-anchor" href="#banner-管理" aria-label="Permalink to &quot;banner 管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「小程序」和「状态」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除 banner</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑 banner 信息</li><li><strong>删除</strong>：删除该 banner</li></ul></li><li>列表展示名称、小程序、类型、跳转类型、跳转地址、状态、排序及图片预览</li></ul><h3 id="首页金刚区" tabindex="-1">首页金刚区 <a class="header-anchor" href="#首页金刚区" aria-label="Permalink to &quot;首页金刚区&quot;">​</a></h3><p>用于配置小程序首页左右并排的金刚区入口卡片，通常展示两个并排的功能入口（如左banner、右banner）。</p><h4 id="添加金刚区入口" tabindex="-1">添加金刚区入口 <a class="header-anchor" href="#添加金刚区入口" aria-label="Permalink to &quot;添加金刚区入口&quot;">​</a></h4><ol><li>进入「小程序页面装修 → 首页金刚区」，点击「新增」</li><li>在弹窗中填写以下信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>✓</td><td>入口名称，如「首页banner(左)」「首页banner（右）」</td></tr><tr><td>小程序</td><td>✓</td><td>选择该入口归属的小程序</td></tr><tr><td>状态</td><td>✓</td><td>启用 / 禁用</td></tr><tr><td>跳转类型</td><td>—</td><td>内部跳转 / 网页跳转 / 小程序跳转</td></tr><tr><td>显示顺序</td><td>—</td><td>数字越小越靠前</td></tr><tr><td>跳转地址</td><td>—</td><td>根据跳转类型填写对应的页面路径或链接</td></tr><tr><td>图片</td><td>—</td><td>上传入口展示图，≤2MB，png/jpg/jpeg，建议尺寸 50×50</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="金刚区管理" tabindex="-1">金刚区管理 <a class="header-anchor" href="#金刚区管理" aria-label="Permalink to &quot;金刚区管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「小程序」和「状态」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除入口</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑入口信息</li><li><strong>删除</strong>：删除该入口</li></ul></li><li>列表展示名称、小程序、类型、跳转类型、跳转地址、状态、排序及图片预览</li></ul><h3 id="个人中心宣传" tabindex="-1">个人中心宣传 <a class="header-anchor" href="#个人中心宣传" aria-label="Permalink to &quot;个人中心宣传&quot;">​</a></h3><p>用于配置小程序个人中心页面的宣传展示图，常用于展示会员权益、积分说明等引导内容。</p><h4 id="添加宣传图" tabindex="-1">添加宣传图 <a class="header-anchor" href="#添加宣传图" aria-label="Permalink to &quot;添加宣传图&quot;">​</a></h4><ol><li>进入「小程序页面装修 → 个人中心宣传」，点击「新增」</li><li>在弹窗中填写以下信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>✓</td><td>宣传图名称，如「个人中心页面」「个人中心宣传图」</td></tr><tr><td>小程序</td><td>✓</td><td>选择该宣传图归属的小程序</td></tr><tr><td>状态</td><td>✓</td><td>启用 / 禁用</td></tr><tr><td>跳转类型</td><td>—</td><td>内部跳转 / 网页跳转 / 小程序跳转</td></tr><tr><td>显示顺序</td><td>—</td><td>数字越小越靠前</td></tr><tr><td>跳转地址</td><td>—</td><td>根据跳转类型填写对应的页面路径或链接</td></tr><tr><td>图片</td><td>—</td><td>上传宣传展示图，≤2MB，png/jpg/jpeg</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="宣传图管理" tabindex="-1">宣传图管理 <a class="header-anchor" href="#宣传图管理" aria-label="Permalink to &quot;宣传图管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「小程序」和「状态」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除宣传图</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑宣传图信息</li><li><strong>删除</strong>：删除该宣传图</li></ul></li><li>列表展示名称、小程序、类型、跳转类型、跳转地址、状态、排序及图片预览</li></ul><h3 id="小程序弹窗" tabindex="-1">小程序弹窗 <a class="header-anchor" href="#小程序弹窗" aria-label="Permalink to &quot;小程序弹窗&quot;">​</a></h3><p>用于配置小程序打开时自动展示的弹窗广告或引导页，支持设置跳转链接及展示状态。</p><blockquote><p><strong>注意</strong>：弹窗开启后，默认自动显示 <strong>6 秒</strong>。</p></blockquote><h4 id="添加弹窗" tabindex="-1">添加弹窗 <a class="header-anchor" href="#添加弹窗" aria-label="Permalink to &quot;添加弹窗&quot;">​</a></h4><ol><li>进入「小程序页面装修 → 小程序弹窗」，点击「新增」</li><li>在弹窗中填写以下信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>✓</td><td>弹窗名称，用于后台识别</td></tr><tr><td>小程序</td><td>✓</td><td>选择该弹窗归属的小程序</td></tr><tr><td>状态</td><td>✓</td><td>启用 / 禁用</td></tr><tr><td>跳转类型</td><td>—</td><td>内部跳转 / 网页跳转 / 小程序跳转</td></tr><tr><td>显示顺序</td><td>—</td><td>数字越小越靠前</td></tr><tr><td>跳转地址</td><td>—</td><td>根据跳转类型填写对应的页面路径或链接</td></tr><tr><td>图片</td><td>—</td><td>上传弹窗展示图，≤2MB，png/jpg/jpeg，建议尺寸 50×50</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="弹窗管理" tabindex="-1">弹窗管理 <a class="header-anchor" href="#弹窗管理" aria-label="Permalink to &quot;弹窗管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「小程序」和「状态」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除弹窗</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑弹窗信息</li><li><strong>删除</strong>：删除该弹窗</li></ul></li><li>列表展示名称、小程序、类型、跳转类型、跳转地址、状态、排序及图片预览</li><li>弹窗启用后，用户打开小程序时自动展示，默认展示时长为 6 秒</li></ul><h3 id="电子海报" tabindex="-1">电子海报 <a class="header-anchor" href="#电子海报" aria-label="Permalink to &quot;电子海报&quot;">​</a></h3><p>用于创建小程序内的电子海报页面，支持配置海报内容、跳转链接，并可生成独立的分享链接与二维码，便于线下扫码传播。</p><h4 id="添加电子海报" tabindex="-1">添加电子海报 <a class="header-anchor" href="#添加电子海报" aria-label="Permalink to &quot;添加电子海报&quot;">​</a></h4><ol><li>进入「小程序页面装修 → 电子海报」，点击「新增」</li><li>在弹窗中填写以下信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>✓</td><td>海报名称，如「签到政策」「停车兑换流程」</td></tr><tr><td>小程序</td><td>✓</td><td>选择该海报归属的小程序</td></tr><tr><td>状态</td><td>✓</td><td>启用 / 禁用</td></tr><tr><td>跳转类型</td><td>—</td><td>内部跳转 / 网页跳转 / 小程序跳转</td></tr><tr><td>显示顺序</td><td>—</td><td>数字越小越靠前</td></tr><tr><td>跳转地址</td><td>—</td><td>根据跳转类型填写对应的页面路径或链接</td></tr><tr><td>图片</td><td>—</td><td>上传海报展示图，≤2MB，png/jpg/jpeg，建议尺寸 50×50</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="电子海报管理" tabindex="-1">电子海报管理 <a class="header-anchor" href="#电子海报管理" aria-label="Permalink to &quot;电子海报管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「小程序」和「状态」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除海报</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑海报信息</li><li><strong>删除</strong>：删除该海报</li><li><strong>生成链接和二维码</strong>：点击后可获取该海报的独立内部跳转链接及二维码，用于线下扫码或分享传播</li></ul></li><li>列表展示名称、小程序、类型、跳转类型、跳转地址、状态、排序及图片预览</li></ul><h3 id="楼层图" tabindex="-1">楼层图 <a class="header-anchor" href="#楼层图" aria-label="Permalink to &quot;楼层图&quot;">​</a></h3><p>用于配置小程序内的商场楼层导览图，展示各楼层的平面布局及商铺分布。</p><blockquote><p><strong>注意</strong>：小程序默认使用「品牌导览」功能。如需切换为「楼层图」模式，<strong>需联系软件商进行版本切换</strong>，后台仅支持楼层图内容配置。</p></blockquote><h4 id="添加楼层" tabindex="-1">添加楼层 <a class="header-anchor" href="#添加楼层" aria-label="Permalink to &quot;添加楼层&quot;">​</a></h4><ol><li>进入「小程序页面装修 → 楼层图」，点击「新增」</li><li>在弹窗中填写以下信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>小程序</td><td>✓</td><td>选择该楼层图归属的小程序</td></tr><tr><td>所属区域</td><td>✓</td><td>选择商场区域，如「鑫科爱琴海购物公园」</td></tr><tr><td>名称</td><td>✓</td><td>楼层名称，如「B1」「1F」「2F」</td></tr><tr><td>图片</td><td>—</td><td>上传楼层平面图，≤2MB，png/jpg/jpeg</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="楼层图管理" tabindex="-1">楼层图管理 <a class="header-anchor" href="#楼层图管理" aria-label="Permalink to &quot;楼层图管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「小程序」和「所属区域」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除楼层</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑楼层信息</li><li><strong>删除</strong>：删除该楼层</li></ul></li><li>列表展示主键、名称及楼层平面图预览</li></ul><hr><h2 id="商户管理" tabindex="-1">商户管理 <a class="header-anchor" href="#商户管理" aria-label="Permalink to &quot;商户管理&quot;">​</a></h2><h3 id="业态楼层信息" tabindex="-1">业态楼层信息 <a class="header-anchor" href="#业态楼层信息" aria-label="Permalink to &quot;业态楼层信息&quot;">​</a></h3><p>用于配置商场的<strong>业态分类</strong>和<strong>楼层信息</strong>，供商户信息管理时进行关联选择，同时也用于小程序内的品牌导览筛选。</p><h4 id="添加业态-楼层" tabindex="-1">添加业态/楼层 <a class="header-anchor" href="#添加业态-楼层" aria-label="Permalink to &quot;添加业态/楼层&quot;">​</a></h4><ol><li>进入「商户管理 → 业态楼层信息」，点击「新增」</li><li>在弹窗中填写以下信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>所属商圈</td><td>✓</td><td>选择归属的商圈/商户</td></tr><tr><td>名称</td><td>✓</td><td>业态或楼层名称</td></tr><tr><td>类型</td><td>✓</td><td><strong>业态</strong>：如零售、餐饮、娱乐等分类<br><strong>楼层</strong>：如 B1层、L1层、L2层等</td></tr><tr><td>排序</td><td>—</td><td>数字越小排序越靠前</td></tr><tr><td>标签名称</td><td>—</td><td>仅「业态」类型可填写，如「一家之主」「家有宝贝」等营销标签</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="业态楼层管理" tabindex="-1">业态楼层管理 <a class="header-anchor" href="#业态楼层管理" aria-label="Permalink to &quot;业态楼层管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「所属商户」「类型」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除，或点击「导出」下载列表</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑业态/楼层信息</li><li><strong>删除</strong>：删除该条记录</li></ul></li><li><strong>类型区分</strong>： <ul><li><strong>楼层类型</strong>：用于标识商场各楼层，如 B1层、L1层、L2层等</li><li><strong>业态类型</strong>：用于标识商户经营分类，如「其它零售」「美容美体眼镜健身娱乐」「钟表黄金电子」等，可附加营销标签</li></ul></li></ul><h3 id="商户信息管理" tabindex="-1">商户信息管理 <a class="header-anchor" href="#商户信息管理" aria-label="Permalink to &quot;商户信息管理&quot;">​</a></h3><p>用于管理商场内各商户/门店的基础信息、部门架构及门店补充资料。</p><h4 id="添加部门" tabindex="-1">添加部门 <a class="header-anchor" href="#添加部门" aria-label="Permalink to &quot;添加部门&quot;">​</a></h4><ol><li>进入「商户管理 → 商户信息管理」，点击「新增」添加部门</li><li>在弹窗中填写部门信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>上级部门</td><td>✓</td><td>选择该部门的父级部门，支持多级部门架构</td></tr><tr><td>部门名称</td><td>✓</td><td>部门名称</td></tr><tr><td>显示排序</td><td>✓</td><td>数字越小排序越靠前</td></tr><tr><td>负责人</td><td>—</td><td>部门负责人姓名</td></tr><tr><td>联系电话</td><td>—</td><td>部门联系电话</td></tr><tr><td>邮箱</td><td>—</td><td>部门联系邮箱</td></tr><tr><td>部门状态</td><td>—</td><td>启用 / 禁用</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="门店补充信息" tabindex="-1">门店补充信息 <a class="header-anchor" href="#门店补充信息" aria-label="Permalink to &quot;门店补充信息&quot;">​</a></h4><blockquote><p><strong>特别说明</strong>：智慧商圈门店 ID 需要与微信、支付宝及美团的商圈内部 ID 保持一致，否则将影响支付积分通联及商圈数据同步。</p></blockquote><ol><li>在商户列表中，点击「补充信息」进入门店资料完善页面</li><li>在弹窗中填写以下信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>门店名称</td><td>系统自动带出，不可修改</td></tr><tr><td>业态</td><td>选择该门店归属的业态分类（需在「业态楼层信息」中预先配置）</td></tr><tr><td>楼层</td><td>选择门店所在楼层（需在「业态楼层信息」中预先配置）</td></tr><tr><td>积分比例</td><td>消费积分计算比例</td></tr><tr><td>联系电话</td><td>门店对外联系电话</td></tr><tr><td>门店编号</td><td>可输入通联商户 AppID，需与微信/支付宝商圈内部 ID 保持一致</td></tr><tr><td>详细地址</td><td>门店详细位置描述</td></tr><tr><td>简介</td><td>门店简介说明</td></tr><tr><td>查询关键字</td><td>用于搜索优化，可输入「新店」或「变更」等标记</td></tr><tr><td>商户号</td><td>可输入通联商户号</td></tr><tr><td>门店logo</td><td>≤2MB，png/jpg/jpeg，建议尺寸 158×158</td></tr><tr><td>主图</td><td>≤2MB，png/jpg/jpeg，建议尺寸 404×686</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="商户管理-1" tabindex="-1">商户管理 <a class="header-anchor" href="#商户管理-1" aria-label="Permalink to &quot;商户管理&quot;">​</a></h4><ul><li><strong>列表展示</strong>：采用树形结构展示商户层级关系，支持展开/收起父级商户查看子商户</li><li><strong>列表字段</strong>：商户名称、主键、商户编号、排序、状态、积分比例、业态、楼层</li><li><strong>搜索筛选</strong>：支持按商户名称、状态等条件筛选</li><li><strong>批量操作</strong>：勾选后可批量修改、删除，或点击「导出」下载商户列表</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑商户基础信息</li><li><strong>+新增</strong>：在该商户下新增子商户</li><li><strong>删除</strong>：删除该商户（仅叶子节点可删除）</li><li><strong>门店补充信息</strong>：完善门店详细资料</li><li><strong>生成链接和二维码</strong>：获取商户分享链接和二维码</li></ul></li></ul><h3 id="账号管理" tabindex="-1">账号管理 <a class="header-anchor" href="#账号管理" aria-label="Permalink to &quot;账号管理&quot;">​</a></h3><p>用于为各门店/商户创建和管理后台登录账号，<strong>支持一个门店配置多个账户</strong>，满足多员工、多角色协作需求。</p><h4 id="添加账号" tabindex="-1">添加账号 <a class="header-anchor" href="#添加账号" aria-label="Permalink to &quot;添加账号&quot;">​</a></h4><ol><li>进入「商户管理 → 账号管理」，点击「新增」</li><li>在弹窗中填写用户信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>用户昵称</td><td>✓</td><td>账号显示名称</td></tr><tr><td>归属部门</td><td>✓</td><td>选择该账号归属的门店/部门</td></tr><tr><td>手机号码</td><td>—</td><td>绑定手机号，用于登录及通知</td></tr><tr><td>邮箱</td><td>—</td><td>绑定邮箱</td></tr><tr><td>用户性别</td><td>—</td><td>男 / 女 / 未知</td></tr><tr><td>状态</td><td>—</td><td>启用 / 禁用</td></tr><tr><td>岗位</td><td>—</td><td>选择岗位，如店长、店员等</td></tr><tr><td>角色</td><td>—</td><td>分配角色权限，支持多选（如「核销员」）</td></tr><tr><td>备注</td><td>—</td><td>账号备注说明</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存，系统将自动生成登录账号</li></ol><h4 id="账号管理-1" tabindex="-1">账号管理 <a class="header-anchor" href="#账号管理-1" aria-label="Permalink to &quot;账号管理&quot;">​</a></h4><ul><li><strong>部门筛选</strong>：左侧展示部门树形结构，点击部门可快速筛选该门店下的所有账号</li><li><strong>搜索筛选</strong>：支持按「部门名称」「登陆账号」「备注」「状态」「创建时间」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除，支持「导入」批量创建账号，或「导出」下载账号列表</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑账号信息</li><li><strong>删除</strong>：删除该账号</li><li><strong>更多</strong>：查看详情或重置密码</li></ul></li><li><strong>状态开关</strong>：列表中可直接切换账号「启用 / 禁用」状态</li></ul><blockquote><p><strong>说明</strong>：一个门店（部门）下可创建多个账号，不同账号可分配不同角色（如核销员、管理员），实现权限分离与协作管理。</p></blockquote><hr><h2 id="商品券管理" tabindex="-1">商品券管理 <a class="header-anchor" href="#商品券管理" aria-label="Permalink to &quot;商品券管理&quot;">​</a></h2><h3 id="普通商品" tabindex="-1">普通商品 <a class="header-anchor" href="#普通商品" aria-label="Permalink to &quot;普通商品&quot;">​</a></h3><p>用于创建和管理小程序内的积分兑换商品、现金购买商品或积分+现金组合商品，支持设置库存、限购、核销规则及上架状态。</p><h4 id="添加商品" tabindex="-1">添加商品 <a class="header-anchor" href="#添加商品" aria-label="Permalink to &quot;添加商品&quot;">​</a></h4><ol><li>进入「商品券管理 → 普通商品」，点击「新增」</li><li>在弹窗中填写商品信息：</li></ol><p><strong>基础信息</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>归属商户</td><td>✓</td><td>选择商品归属的商户</td></tr><tr><td>核销商户</td><td>✓</td><td>选择可核销该商品的商户（支持多选）</td></tr><tr><td>商品名称</td><td>✓</td><td>商品展示名称</td></tr><tr><td>所属小程序</td><td>✓</td><td>选择商品归属的小程序</td></tr><tr><td>所属活动</td><td>✓</td><td>选择商品参与的活动，如「周四秒杀商品」</td></tr><tr><td>商品开始购买日期</td><td>✓</td><td>设置商品开放购买的起始时间</td></tr></tbody></table><p><strong>核销时间</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>核销开始日期</td><td>✓</td><td>券码可核销的起始日期</td></tr><tr><td>核销结束日期</td><td>✓</td><td>券码可核销的截止日期</td></tr><tr><td>核销起始时间</td><td>—</td><td>每日可核销的开始时间，如 10:00</td></tr><tr><td>核销结束时间</td><td>—</td><td>每日可核销的结束时间，如 23:59</td></tr></tbody></table><p><strong>库存与价格</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>库存</td><td>✓</td><td>商品总库存数量</td></tr><tr><td>每天限购库存</td><td>—</td><td>每日可售出的限量库存</td></tr><tr><td>原价</td><td>✓</td><td>商品划线原价</td></tr><tr><td>实际支付价格</td><td>—</td><td>用户需支付的现金金额，0 表示纯积分兑换</td></tr><tr><td>积分金额</td><td>—</td><td>兑换所需积分数量</td></tr><tr><td>用户总限购量</td><td>—</td><td>每个用户最多可购买的总数量</td></tr><tr><td>用户每天限购量</td><td>—</td><td>每个用户每天最多可购买的数量</td></tr><tr><td>购买N天有效</td><td>—</td><td>购买后 N 天内有效（0 表示按核销日期）</td></tr><tr><td>显示顺序</td><td>—</td><td>数字越小排序越靠前，默认 0</td></tr></tbody></table><p><strong>状态与规则</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>状态</td><td>上架 / 下架</td></tr><tr><td>是否过期退</td><td>过期后是否支持退款</td></tr><tr><td>是否随时退</td><td>是否支持随时退款（需保证微信支付平台足够留存资金）</td></tr><tr><td>是否启用距离限制使用</td><td>是否限制用户必须在商场附近核销（需联系技术人员开启；小程序管理配置定位，默认 1.5 公里）</td></tr><tr><td>是否开启赠券功能</td><td>是否允许将券转赠给他人</td></tr><tr><td>是否开启多张赠送模式</td><td>是否支持一次赠送多张</td></tr></tbody></table><p><strong>图片与说明</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>商品主图</td><td>≤2MB，png/jpg/jpeg，建议尺寸 280×280</td></tr><tr><td>商品明细图</td><td>≤2MB，png/jpg/jpeg，建议尺寸 686×宽不限</td></tr><tr><td>使用说明</td><td>富文本编辑器，可填写兑换规则、使用时间、地点等信息</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="商品管理" tabindex="-1">商品管理 <a class="header-anchor" href="#商品管理" aria-label="Permalink to &quot;商品管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「所属商户」「商品名称」「券号」「状态」「小程序」「所属活动」「积分」「金额」「核销时间」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除，或点击「导出」下载商品列表</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑商品信息</li><li><strong>删除</strong>：删除该商品</li><li><strong>复制</strong>：快速复制当前商品配置创建新商品</li><li><strong>生成链接和二维码</strong>：获取商品分享链接和二维码</li></ul></li><li><strong>状态开关</strong>：列表中可直接切换商品「上架 / 下架」状态</li></ul><h3 id="拼团商品" tabindex="-1">拼团商品 <a class="header-anchor" href="#拼团商品" aria-label="Permalink to &quot;拼团商品&quot;">​</a></h3><p>用于创建和管理拼团活动商品，用户发起拼团后需邀请指定人数参团，达到成团人数即可成团购买。</p><h4 id="添加拼团商品" tabindex="-1">添加拼团商品 <a class="header-anchor" href="#添加拼团商品" aria-label="Permalink to &quot;添加拼团商品&quot;">​</a></h4><ol><li>进入「商品券管理 → 拼团商品」，点击「新增」</li><li>在弹窗中填写商品信息：</li></ol><p><strong>基础信息</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>归属商户</td><td>✓</td><td>选择商品归属的商户</td></tr><tr><td>核销商户</td><td>✓</td><td>选择可核销该商品的商户（支持多选）</td></tr><tr><td>商品名称</td><td>✓</td><td>商品展示名称</td></tr><tr><td>所属小程序</td><td>✓</td><td>选择商品归属的小程序</td></tr></tbody></table><p><strong>核销时间</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>核销开始日期</td><td>✓</td><td>券码可核销的起始日期</td></tr><tr><td>核销结束日期</td><td>✓</td><td>券码可核销的截止日期</td></tr></tbody></table><p><strong>库存与价格</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>库存</td><td>✓</td><td>商品总库存数量</td></tr><tr><td>实际支付价格</td><td>✓</td><td>拼团成功后用户需支付的金额（拼团价）</td></tr><tr><td>原价</td><td>✓</td><td>商品划线原价</td></tr></tbody></table><p><strong>拼团规则</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>几人团</td><td>成团所需人数，如 2 人团、3 人团（填写 0 表示不限）</td></tr><tr><td>拼团结束日期</td><td>拼团活动的截止日期</td></tr><tr><td>状态</td><td>上架 / 下架</td></tr></tbody></table><p><strong>图片与说明</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>商品主图</td><td>≤2MB，png/jpg/jpeg</td></tr><tr><td>商品明细图</td><td>≤2MB，png/jpg/jpeg，建议尺寸 686×高不限</td></tr><tr><td>使用说明</td><td>富文本编辑器，可填写拼团规则、使用说明等信息</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="拼团商品管理" tabindex="-1">拼团商品管理 <a class="header-anchor" href="#拼团商品管理" aria-label="Permalink to &quot;拼团商品管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「所属商户」「商品名称」「状态」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除，或点击「导出」下载商品列表</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑拼团商品信息</li><li><strong>删除</strong>：删除该商品</li><li><strong>生成链接</strong>：获取拼团商品分享链接</li></ul></li><li><strong>状态开关</strong>：列表中可直接切换商品「上架 / 下架」状态</li></ul><h3 id="组合商品" tabindex="-1">组合商品 <a class="header-anchor" href="#组合商品" aria-label="Permalink to &quot;组合商品&quot;">​</a></h3><p>用于创建组合型商品（如礼包、套餐），由<strong>主商品</strong>和<strong>子商品库</strong>构成。用户购买主商品后，可获得主商品下的全部子商品。</p><h4 id="添加组合商品-主商品" tabindex="-1">添加组合商品（主商品） <a class="header-anchor" href="#添加组合商品-主商品" aria-label="Permalink to &quot;添加组合商品（主商品）&quot;">​</a></h4><ol><li>进入「商品券管理 → 组合商品」，点击「新增」</li><li>在弹窗中填写主商品信息：</li></ol><p><strong>基础信息</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>归属商户</td><td>✓</td><td>选择商品归属的商户</td></tr><tr><td>核销商户</td><td>✓</td><td>选择可核销该商品的商户（支持多选）</td></tr><tr><td>商品名称</td><td>✓</td><td>商品展示名称，如「春日萌友游园会」</td></tr><tr><td>所属小程序</td><td>✓</td><td>选择商品归属的小程序</td></tr><tr><td>所属活动</td><td>✓</td><td>选择商品参与的活动</td></tr></tbody></table><p><strong>核销时间</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>核销开始时间</td><td>✓</td><td>券码可核销的起始日期</td></tr><tr><td>核销结束时间</td><td>✓</td><td>券码可核销的截止日期</td></tr></tbody></table><p><strong>库存与价格</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>库存</td><td>✓</td><td>商品总库存数量</td></tr><tr><td>每天限购库存</td><td>—</td><td>每日可售出的限量库存</td></tr><tr><td>原价</td><td>✓</td><td>商品划线原价</td></tr><tr><td>实际支付价格</td><td>—</td><td>用户需支付的现金金额，0 表示纯积分兑换</td></tr><tr><td>积分金额</td><td>—</td><td>兑换所需积分数量</td></tr><tr><td>用户总限购量</td><td>—</td><td>每个用户最多可购买的总数量</td></tr><tr><td>用户每天限购量</td><td>—</td><td>每个用户每天最多可购买的数量</td></tr><tr><td>购买N天有效</td><td>—</td><td>购买后 N 天内有效（0 表示按核销日期）</td></tr><tr><td>显示顺序</td><td>—</td><td>数字越小排序越靠前</td></tr></tbody></table><p><strong>状态与图片</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>状态</td><td>上架 / 下架</td></tr><tr><td>商品主图</td><td>≤2MB，png/jpg/jpeg</td></tr><tr><td>商品明细图</td><td>≤2MB，png/jpg/jpeg</td></tr><tr><td>使用说明</td><td>富文本编辑器，填写活动规则、兑换说明等</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="配置组合子商品" tabindex="-1">配置组合子商品 <a class="header-anchor" href="#配置组合子商品" aria-label="Permalink to &quot;配置组合子商品&quot;">​</a></h4><blockquote><p><strong>操作流程</strong>：主商品创建完成后，点击列表中的「商品名称」进入「组合子商品」页面，配置该组合包包含的具体子商品。</p></blockquote><ol><li>在组合商品列表中，点击目标商品的「商品名称」</li><li>进入「组合子商品」页面，点击「新增」添加子商品：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>归属商户</td><td>✓</td><td>选择子商品归属的商户</td></tr><tr><td>商品名称</td><td>✓</td><td>子商品名称，如「春日萌友游园会-丢沙包」</td></tr><tr><td>原价</td><td>✓</td><td>子商品原价</td></tr><tr><td>商品主图</td><td>—</td><td>≤2MB，png/jpg/jpeg</td></tr><tr><td>使用说明</td><td>—</td><td>富文本编辑器，填写该子商品的独立使用规则</td></tr></tbody></table><ol start="3"><li>子商品支持单独配置「核销开始时间」和「核销结束时间」</li><li>确认后保存，可继续添加多个子商品</li></ol><h4 id="组合商品管理" tabindex="-1">组合商品管理 <a class="header-anchor" href="#组合商品管理" aria-label="Permalink to &quot;组合商品管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「所属商户」「商品名称」「状态」等条件筛选</li><li><strong>批量操作</strong>：勾选后可批量修改、删除，或点击「导出」下载商品列表</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑主商品信息</li><li><strong>删除</strong>：删除该主商品（连带删除所有子商品）</li><li><strong>生成链接和二维码</strong>：获取组合商品分享链接和二维码</li><li><strong>点击商品名称</strong>：进入该商品的「组合子商品」配置页面</li></ul></li><li><strong>状态开关</strong>：列表中可直接切换主商品「上架 / 下架」状态</li></ul><hr><h2 id="会员停车管理" tabindex="-1">会员停车管理 <a class="header-anchor" href="#会员停车管理" aria-label="Permalink to &quot;会员停车管理&quot;">​</a></h2><h3 id="停车优惠券" tabindex="-1">停车优惠券 <a class="header-anchor" href="#停车优惠券" aria-label="Permalink to &quot;停车优惠券&quot;">​</a></h3><p>用于配置小程序内的停车抵扣券，会员可使用积分兑换停车时长减免券，支持对接多种第三方停车系统。</p><h4 id="添加停车券" tabindex="-1">添加停车券 <a class="header-anchor" href="#添加停车券" aria-label="Permalink to &quot;添加停车券&quot;">​</a></h4><ol><li>进入「会员停车管理 → 停车优惠券」，点击「新增」</li><li>在弹窗中填写停车券信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>归属商户</td><td>✓</td><td>选择停车券归属的商户</td></tr><tr><td>商品名称</td><td>✓</td><td>停车券展示名称，如「工作日免费1小时停车券」</td></tr><tr><td>所属小程序</td><td>✓</td><td>选择停车券归属的小程序</td></tr><tr><td>库存</td><td>✓</td><td>停车券总库存数量</td></tr><tr><td>可用星期</td><td>—</td><td>勾选该停车券可使用的星期，支持多选（周一至周日）</td></tr><tr><td>停车系统</td><td>—</td><td>选择对接的停车系统，支持：<strong>立方停车</strong>、<strong>科拓停车</strong>、<strong>宜泊停车</strong>、<strong>ETCP停车</strong></td></tr><tr><td>积分金额</td><td>—</td><td>兑换所需积分数量，0 表示免费领取</td></tr><tr><td>车牌每天限购量</td><td>—</td><td>每个车牌每天最多可兑换的数量</td></tr><tr><td>显示顺序</td><td>—</td><td>数字越小排序越靠前</td></tr><tr><td>抵扣时长(分钟)</td><td>—</td><td>该券可抵扣的停车时长，如 60 分钟</td></tr><tr><td>抵扣金额</td><td>—</td><td>该券可抵扣的停车费用金额</td></tr><tr><td>状态</td><td>—</td><td>上架 / 下架</td></tr></tbody></table><p><strong>图片与说明</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>商品主图</td><td>≤2MB，png/jpg/jpeg</td></tr><tr><td>商品明细图</td><td>≤2MB，png/jpg/jpeg</td></tr><tr><td>使用说明</td><td>富文本编辑器，填写使用规则、适用停车场、注意事项等</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="停车券管理" tabindex="-1">停车券管理 <a class="header-anchor" href="#停车券管理" aria-label="Permalink to &quot;停车券管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「所属商户」「商品名称」「状态」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除，或点击「导出」下载停车券列表</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑停车券信息</li><li><strong>删除</strong>：删除该停车券</li></ul></li><li><strong>状态开关</strong>：列表中可直接切换停车券「上架 / 下架」状态</li></ul><h3 id="停车支付订单" tabindex="-1">停车支付订单 <a class="header-anchor" href="#停车支付订单" aria-label="Permalink to &quot;停车支付订单&quot;">​</a></h3><p>用于查看用户通过小程序线上缴纳停车费的订单记录。</p><blockquote><p><strong>前提条件</strong>：需先打通「线上缴纳停车费」功能模块，方可在此查看停车支付数据。</p><p><strong>说明</strong>：纯停车券（积分兑换的停车抵扣券）的兑换及核销记录，请前往「订单中心 → 核销明细」查看。</p></blockquote><h4 id="订单查询" tabindex="-1">订单查询 <a class="header-anchor" href="#订单查询" aria-label="Permalink to &quot;订单查询&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「订单号」「车牌号」「支付时间」筛选，点击「重置」清空条件</li><li><strong>导出</strong>：点击「导出」可下载停车支付订单列表</li><li><strong>列表字段</strong>：</li></ul><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>订单号</td><td>系统生成的停车支付订单编号</td></tr><tr><td>商户名称</td><td>停车场归属的商户/商场</td></tr><tr><td>车牌号</td><td>缴费车辆的车牌号码</td></tr><tr><td>支付金额</td><td>实际支付的停车费用</td></tr><tr><td>支付状态</td><td>已支付 / 待支付 / 已退款</td></tr><tr><td>支付时间</td><td>用户完成支付的时间</td></tr><tr><td>支付单号</td><td>第三方支付平台流水号</td></tr></tbody></table><hr><h2 id="会员中心" tabindex="-1">会员中心 <a class="header-anchor" href="#会员中心" aria-label="Permalink to &quot;会员中心&quot;">​</a></h2><h3 id="会员列表" tabindex="-1">会员列表 <a class="header-anchor" href="#会员列表" aria-label="Permalink to &quot;会员列表&quot;">​</a></h3><p>用于查看和管理小程序注册会员的信息，支持多维筛选、批量导入导出及单会员精细化操作。</p><h4 id="会员查询" tabindex="-1">会员查询 <a class="header-anchor" href="#会员查询" aria-label="Permalink to &quot;会员查询&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持多维度组合筛选： <ul><li>「小程序」选择归属小程序</li><li>「手机号」精确或模糊搜索</li><li>「会员标签」按标签筛选</li><li>「昵称」搜索微信昵称</li><li>「备注」搜索备注内容</li><li>「注册时间」选择日期范围</li><li>「积分范围」输入开始/结束积分</li><li>「生日搜索」按年份、月份筛选</li><li>「会员等级搜索」按等级筛选</li></ul></li><li><strong>重置</strong>：点击「重置」清空所有筛选条件</li><li><strong>批量操作</strong>： <ul><li>「导入」批量导入会员数据</li><li>「导出」下载会员列表</li></ul></li></ul><h4 id="列表字段" tabindex="-1">列表字段 <a class="header-anchor" href="#列表字段" aria-label="Permalink to &quot;列表字段&quot;">​</a></h4><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>微信昵称</td><td>会员微信昵称</td></tr><tr><td>手机号</td><td>绑定手机号</td></tr><tr><td>积分</td><td>当前可用积分</td></tr><tr><td>姓名</td><td>会员真实姓名</td></tr><tr><td>生日</td><td>会员生日</td></tr><tr><td>会员等级</td><td>当前会员等级</td></tr><tr><td>会员标签</td><td>所属标签</td></tr><tr><td>注册时间</td><td>首次注册日期</td></tr><tr><td>备注</td><td>会员备注信息</td></tr></tbody></table><h4 id="会员操作-右侧功能按钮" tabindex="-1">会员操作（右侧功能按钮） <a class="header-anchor" href="#会员操作-右侧功能按钮" aria-label="Permalink to &quot;会员操作（右侧功能按钮）&quot;">​</a></h4><p>每行会员数据右侧提供以下操作按钮：</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>发券</td><td>向该会员单独发放优惠券</td></tr><tr><td>补录积分</td><td>手动为该会员补录积分（正数增加/负数扣减）</td></tr><tr><td>券包记录</td><td>查看该会员的优惠券领取、使用、过期记录</td></tr><tr><td>积分明细</td><td>查看该会员的积分获取与消耗明细流水</td></tr><tr><td>备注</td><td>编辑该会员的备注信息</td></tr><tr><td>删除</td><td>删除该会员账号（谨慎操作）</td></tr></tbody></table><h3 id="等级管理" tabindex="-1">等级管理 <a class="header-anchor" href="#等级管理" aria-label="Permalink to &quot;等级管理&quot;">​</a></h3><p>用于配置会员等级体系及每个等级的专属权益，<strong>每个会员等级都可配置独立的券包福利</strong>。</p><h4 id="添加会员等级" tabindex="-1">添加会员等级 <a class="header-anchor" href="#添加会员等级" aria-label="Permalink to &quot;添加会员等级&quot;">​</a></h4><ol><li>进入「会员中心 → 等级管理」，点击「新增」</li><li>在弹窗中填写等级信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>所属小程序</td><td>✓</td><td>选择该等级归属的小程序</td></tr><tr><td>级别名称</td><td>✓</td><td>等级名称，如「新悦会员」「尊享会员」</td></tr><tr><td>折扣价</td><td>✓</td><td>享受会员折扣价（百分比，如 100 表示无折扣）</td></tr><tr><td>等级次序</td><td>✓</td><td>数字越大等级越高，如 1、2、3、4</td></tr><tr><td>升级规则</td><td>✓</td><td>本年度内支付即积分达到指定值即可达标升级</td></tr><tr><td>备注</td><td>—</td><td>等级说明备注</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="等级管理-1" tabindex="-1">等级管理 <a class="header-anchor" href="#等级管理-1" aria-label="Permalink to &quot;等级管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「所属小程序」「级别名称」筛选</li><li><strong>批量操作</strong>：勾选后可批量修改、删除，或点击「导出」下载等级列表</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑等级信息</li><li><strong>删除</strong>：删除该等级</li><li><strong>券包福利</strong>：进入该等级的专属券包福利配置页面</li></ul></li></ul><hr><h3 id="券包福利配置" tabindex="-1">券包福利配置 <a class="header-anchor" href="#券包福利配置" aria-label="Permalink to &quot;券包福利配置&quot;">​</a></h3><blockquote><p><strong>说明</strong>：每个会员等级都有独立的券包福利。在「等级管理」中点击「券包福利」，即可为该等级配置专属优惠券/礼品券。</p></blockquote><h4 id="添加券包福利" tabindex="-1">添加券包福利 <a class="header-anchor" href="#添加券包福利" aria-label="Permalink to &quot;添加券包福利&quot;">​</a></h4><ol><li>进入等级对应的「券包福利配置」页面，点击「新增」</li><li>在弹窗中填写福利信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>归属商户</td><td>✓</td><td>选择福利归属的商户</td></tr><tr><td>核销商户</td><td>✓</td><td>选择可核销该福利的商户</td></tr><tr><td>商品名称</td><td>✓</td><td>福利名称，如「100元无门槛券」「2小时停车优惠券」</td></tr><tr><td>核销开始时间</td><td>✓</td><td>券码可核销的起始时间</td></tr><tr><td>核销结束时间</td><td>✓</td><td>券码可核销的截止时间</td></tr><tr><td>用户总限购量</td><td>✓</td><td>每个用户最多可领取的数量</td></tr><tr><td>库存</td><td>✓</td><td>福利总库存数量</td></tr><tr><td>是否每月能领取</td><td>—</td><td>是 / 否，开启后会员每月可重复领取</td></tr><tr><td>购买N天有效</td><td>—</td><td>领取后 N 天内有效</td></tr><tr><td>商品主图</td><td>—</td><td>≤2MB，png/jpg/jpeg，建议尺寸 500×500</td></tr><tr><td>使用说明</td><td>—</td><td>富文本编辑器，填写使用规则</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="券包福利管理" tabindex="-1">券包福利管理 <a class="header-anchor" href="#券包福利管理" aria-label="Permalink to &quot;券包福利管理&quot;">​</a></h4><ul><li><strong>列表字段</strong>：商品主图、商品名称、库存、已售库存、是否每月能领取</li><li><strong>批量操作</strong>：勾选后可批量修改、删除</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑券包福利信息</li><li><strong>删除</strong>：删除该福利</li></ul></li></ul><hr><h2 id="会员营销活动" tabindex="-1">会员营销活动 <a class="header-anchor" href="#会员营销活动" aria-label="Permalink to &quot;会员营销活动&quot;">​</a></h2><p>会员营销活动模块提供多种互动营销工具，用于提升会员活跃度和留存率。</p><h3 id="大转盘" tabindex="-1">大转盘 <a class="header-anchor" href="#大转盘" aria-label="Permalink to &quot;大转盘&quot;">​</a></h3><p>用于创建积分抽奖活动，会员消耗积分参与转盘抽奖。配置分为<strong>活动基础信息</strong>和<strong>抽奖商品</strong>两步。</p><h4 id="添加大转盘活动" tabindex="-1">添加大转盘活动 <a class="header-anchor" href="#添加大转盘活动" aria-label="Permalink to &quot;添加大转盘活动&quot;">​</a></h4><ol><li>进入「会员中心 → 会员营销活动 → 大转盘」，点击「新增」</li><li>在弹窗中配置活动信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>游戏名称</td><td>✓</td><td>活动名称</td></tr><tr><td>小程序</td><td>✓</td><td>选择活动归属的小程序</td></tr><tr><td>游戏开始日期</td><td>—</td><td>活动开始日期</td></tr><tr><td>游戏结束日期</td><td>—</td><td>活动结束日期</td></tr><tr><td>游戏起始时间</td><td>—</td><td>每日可参与的开始时间，如 10:00</td></tr><tr><td>游戏结束时间</td><td>—</td><td>每日可参与的结束时间，如 22:00</td></tr><tr><td>消耗积分数/次</td><td>—</td><td>每次抽奖消耗的积分数量</td></tr><tr><td>每天抽奖次数</td><td>—</td><td>每个用户每天最多可抽奖次数</td></tr><tr><td>总抽奖次数</td><td>—</td><td>每个用户活动期间最多可抽奖总次数</td></tr><tr><td>状态</td><td>—</td><td>启用 / 禁用</td></tr></tbody></table><p><strong>图片素材</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>背景图</td><td>建议尺寸 750×1334</td></tr><tr><td>转盘图</td><td>建议尺寸 573×580</td></tr><tr><td>按钮图</td><td>建议尺寸 134×134</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="配置抽奖商品" tabindex="-1">配置抽奖商品 <a class="header-anchor" href="#配置抽奖商品" aria-label="Permalink to &quot;配置抽奖商品&quot;">​</a></h4><blockquote><p><strong>操作流程</strong>：活动创建完成后，点击列表中的「商品配置」，进入该活动的奖品配置页面。</p></blockquote><ol><li>在大转盘列表中，点击目标活动的「商品配置」</li><li>进入「游戏配置商品」页面，点击「新增」添加奖品：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>归属商户</td><td>✓</td><td>选择奖品归属的商户</td></tr><tr><td>核销商户</td><td>✓</td><td>选择可核销该奖品的商户（支持多选）</td></tr><tr><td>商品名称</td><td>✓</td><td>奖品名称</td></tr><tr><td>核销开始时间</td><td>✓</td><td>奖品券码可核销的起始日期</td></tr><tr><td>核销结束时间</td><td>✓</td><td>奖品券码可核销的截止日期</td></tr><tr><td>库存</td><td>✓</td><td>奖品总库存数量</td></tr><tr><td>抽奖概率</td><td>✓</td><td>该奖品的中奖概率（数值）</td></tr><tr><td>显示顺序</td><td>✓</td><td>数字越小排序越靠前</td></tr><tr><td>商品主图</td><td>—</td><td>≤2MB，png/jpg/jpeg，建议尺寸 500×500</td></tr><tr><td>使用说明</td><td>—</td><td>富文本编辑器，填写奖品使用规则</td></tr></tbody></table><ol start="3"><li>确认后保存，可继续添加多个奖品</li></ol><h4 id="大转盘管理" tabindex="-1">大转盘管理 <a class="header-anchor" href="#大转盘管理" aria-label="Permalink to &quot;大转盘管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「小程序」「游戏名称」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑活动信息</li><li><strong>删除</strong>：删除该活动</li><li><strong>商品配置</strong>：进入该活动的奖品配置页面</li></ul></li></ul><h3 id="签到" tabindex="-1">签到 <a class="header-anchor" href="#签到" aria-label="Permalink to &quot;签到&quot;">​</a></h3><p>用于配置每日签到活动，会员每日签到可获得积分奖励。</p><h4 id="添加签到活动" tabindex="-1">添加签到活动 <a class="header-anchor" href="#添加签到活动" aria-label="Permalink to &quot;添加签到活动&quot;">​</a></h4><ol><li>进入「会员中心 → 会员营销活动 → 签到」，点击「新增」</li><li>在弹窗中配置活动信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>游戏名称</td><td>✓</td><td>活动名称，如「每日签到」</td></tr><tr><td>小程序</td><td>✓</td><td>选择活动归属的小程序</td></tr><tr><td>签到获得积分数量</td><td>—</td><td>每次签到可获得的积分数</td></tr><tr><td>状态</td><td>—</td><td>启用 / 禁用</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="签到管理" tabindex="-1">签到管理 <a class="header-anchor" href="#签到管理" aria-label="Permalink to &quot;签到管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「小程序」筛选</li><li><strong>批量操作</strong>：勾选后可批量修改、删除</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑签到活动信息</li><li><strong>删除</strong>：删除该签到活动</li></ul></li><li><strong>状态开关</strong>：列表中可直接切换签到活动「启用 / 禁用」状态</li></ul><h3 id="问卷调查" tabindex="-1">问卷调查 <a class="header-anchor" href="#问卷调查" aria-label="Permalink to &quot;问卷调查&quot;">​</a></h3><p>用于创建会员问卷调研，支持可视化拖拽编辑。问卷配置完成后可生成分享链接，放置于首页活动、弹窗等模块中引导会员填写，完成问卷可获积分或券奖励。</p><h4 id="创建问卷" tabindex="-1">创建问卷 <a class="header-anchor" href="#创建问卷" aria-label="Permalink to &quot;创建问卷&quot;">​</a></h4><ol><li>进入「会员中心 → 会员营销活动 → 问卷调查（高级版）」，点击「新建」</li><li>从左侧组件库拖拽所需组件到中间画布区域：</li></ol><p><strong>基础组件</strong></p><table tabindex="0"><thead><tr><th>组件</th><th>说明</th></tr></thead><tbody><tr><td>单行输入</td><td>短文本输入框，适合姓名、简短回答等</td></tr><tr><td>多行输入</td><td>长文本输入框，适合意见建议等</td></tr><tr><td>单选框</td><td>单选题，会员只能选择一项</td></tr><tr><td>多选框</td><td>多选题，会员可选择多项</td></tr><tr><td>下拉选择</td><td>下拉菜单选择，节省页面空间</td></tr></tbody></table><p><strong>高级组件</strong></p><table tabindex="0"><thead><tr><th>组件</th><th>说明</th></tr></thead><tbody><tr><td>日期选择</td><td>日期选择器，适合收集生日、预约日期等</td></tr><tr><td>手机号</td><td>手机号输入框，带格式校验</td></tr><tr><td>邮箱</td><td>邮箱输入框，带格式校验</td></tr></tbody></table><ol start="3"><li>拖拽组件后，在右侧「组件属性」面板中配置题目内容、选项、是否必填等属性</li><li>在「全局外观」中可配置问卷整体样式</li><li>配置完成后点击「保存」</li></ol><h4 id="问卷管理" tabindex="-1">问卷管理 <a class="header-anchor" href="#问卷管理" aria-label="Permalink to &quot;问卷管理&quot;">​</a></h4><ul><li><strong>我的问卷</strong>：查看已创建的问卷列表</li><li><strong>更多操作</strong>：支持复制问卷、删除问卷、生成分享链接等</li><li><strong>分享链接</strong>：问卷保存后可生成专属链接，可复制到「首页活动」「小程序弹窗」「电子海报」等模块中作为跳转入口</li></ul><h3 id="报名活动" tabindex="-1">报名活动 <a class="header-anchor" href="#报名活动" aria-label="Permalink to &quot;报名活动&quot;">​</a></h3><p>用于创建线下活动的在线报名通道，支持名额限制、报名收费/积分兑换、名单管理及核销。</p><h4 id="添加报名活动" tabindex="-1">添加报名活动 <a class="header-anchor" href="#添加报名活动" aria-label="Permalink to &quot;添加报名活动&quot;">​</a></h4><ol><li>进入「会员中心 → 会员营销活动 → 报名活动」，点击「新增」</li><li>在弹窗中配置活动信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>活动名称</td><td>✓</td><td>报名活动名称</td></tr><tr><td>小程序</td><td>✓</td><td>选择活动归属的小程序</td></tr><tr><td>报名开始日期</td><td>—</td><td>报名通道开启日期</td></tr><tr><td>报名结束日期</td><td>—</td><td>报名通道关闭日期</td></tr><tr><td>活动参与日期</td><td>—</td><td>线下活动实际举办日期</td></tr><tr><td>活动参与时间</td><td>—</td><td>线下活动开始时间</td></tr><tr><td>报名金额</td><td>—</td><td>报名费用，0 表示免费报名</td></tr><tr><td>报名积分</td><td>—</td><td>报名所需积分，0 表示不需要积分</td></tr><tr><td>报名人数</td><td>—</td><td>活动名额上限</td></tr><tr><td>报名次数</td><td>—</td><td>每个用户可报名次数</td></tr><tr><td>活动类型</td><td>—</td><td>选择活动分类</td></tr><tr><td>活动地址</td><td>—</td><td>线下活动举办地点</td></tr><tr><td>banner图</td><td>—</td><td>≤1MB，png/jpg/jpeg，建议尺寸 710×300</td></tr><tr><td>活动介绍</td><td>—</td><td>富文本编辑器，填写活动详情、规则说明</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="报名活动管理" tabindex="-1">报名活动管理 <a class="header-anchor" href="#报名活动管理" aria-label="Permalink to &quot;报名活动管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「小程序」「游戏名称」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑活动信息</li><li><strong>删除</strong>：删除该活动</li><li><strong>报名名单</strong>：查看已报名会员列表，支持核销签到</li><li><strong>下载</strong>：下载报名名单 Excel</li></ul></li><li><strong>状态开关</strong>：列表中可直接切换活动「启用 / 禁用」状态</li></ul><h3 id="会员拉新" tabindex="-1">会员拉新 <a class="header-anchor" href="#会员拉新" aria-label="Permalink to &quot;会员拉新&quot;">​</a></h3><p>用于创建老会员邀请新会员注册的拉新活动，老会员分享活动链接，新用户通过链接注册后，双方均可获得相应奖励。</p><h4 id="添加拉新活动" tabindex="-1">添加拉新活动 <a class="header-anchor" href="#添加拉新活动" aria-label="Permalink to &quot;添加拉新活动&quot;">​</a></h4><ol><li>进入「会员中心 → 会员营销活动 → 会员拉新」，点击「新增」</li><li>在弹窗中配置活动信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>小程序</td><td>✓</td><td>选择活动归属的小程序</td></tr><tr><td>活动名称</td><td>✓</td><td>拉新活动名称</td></tr><tr><td>活动展示图</td><td>—</td><td>≤2MB，png/jpg/jpeg，建议尺寸 750×520</td></tr><tr><td>活动规则</td><td>—</td><td>富文本编辑器，填写活动规则、奖励说明等</td></tr><tr><td>新人注册奖励</td><td>—</td><td>新用户注册后可获得的奖励，如「无优惠」「商品券」等</td></tr><tr><td>推荐人奖励</td><td>—</td><td>老会员成功邀请后可获得的奖励</td></tr><tr><td>拉新人次</td><td>—</td><td>每位老会员最多可邀请的人次</td></tr><tr><td>状态</td><td>—</td><td>启用 / 禁用</td></tr><tr><td>备注</td><td>—</td><td>活动备注说明</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="拉新活动管理" tabindex="-1">拉新活动管理 <a class="header-anchor" href="#拉新活动管理" aria-label="Permalink to &quot;拉新活动管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「小程序」「名称」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除，或点击「导出」下载活动列表</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑活动信息</li><li><strong>删除</strong>：删除该活动</li><li><strong>生成链接</strong>：获取活动分享链接，老会员可通过该链接邀请新用户</li></ul></li></ul><h3 id="盲盒抽奖" tabindex="-1">盲盒抽奖 <a class="header-anchor" href="#盲盒抽奖" aria-label="Permalink to &quot;盲盒抽奖&quot;">​</a></h3><p>用于创建盲盒抽奖活动，会员消耗积分参与抽取随机奖品。配置流程与大转盘类似，分为<strong>活动基础信息</strong>和<strong>抽奖商品</strong>两步。</p><h4 id="添加盲盒抽奖活动" tabindex="-1">添加盲盒抽奖活动 <a class="header-anchor" href="#添加盲盒抽奖活动" aria-label="Permalink to &quot;添加盲盒抽奖活动&quot;">​</a></h4><ol><li>进入「会员中心 → 会员营销活动 → 盲盒抽奖」，点击「新增」</li><li>在弹窗中配置活动信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>游戏名称</td><td>✓</td><td>活动名称</td></tr><tr><td>小程序</td><td>✓</td><td>选择活动归属的小程序</td></tr><tr><td>游戏开始日期</td><td>—</td><td>活动开始日期</td></tr><tr><td>游戏结束日期</td><td>—</td><td>活动结束日期</td></tr><tr><td>游戏起始时间</td><td>—</td><td>每日可参与的开始时间</td></tr><tr><td>游戏结束时间</td><td>—</td><td>每日可参与的结束时间</td></tr><tr><td>消耗积分数/次</td><td>—</td><td>每次抽奖消耗的积分数量</td></tr><tr><td>每天抽奖次数</td><td>—</td><td>每个用户每天最多可抽奖次数</td></tr><tr><td>总抽奖次数</td><td>—</td><td>每个用户活动期间最多可抽奖总次数</td></tr><tr><td>状态</td><td>—</td><td>启用 / 禁用</td></tr><tr><td>活动规则</td><td>—</td><td>富文本编辑器，填写活动规则</td></tr></tbody></table><ol start="3"><li>确认无误后点击「确定」保存</li></ol><h4 id="配置抽奖商品-1" tabindex="-1">配置抽奖商品 <a class="header-anchor" href="#配置抽奖商品-1" aria-label="Permalink to &quot;配置抽奖商品&quot;">​</a></h4><blockquote><p><strong>操作流程</strong>：活动创建完成后，点击列表中的「商品配置」，进入该活动的奖品配置页面。</p></blockquote><ol><li>在盲盒抽奖列表中，点击目标活动的「商品配置」</li><li>进入「游戏配置商品」页面，点击「新增」添加奖品：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>归属商户</td><td>✓</td><td>选择奖品归属的商户</td></tr><tr><td>核销商户</td><td>✓</td><td>选择可核销该奖品的商户（支持多选）</td></tr><tr><td>商品名称</td><td>✓</td><td>奖品名称</td></tr><tr><td>核销开始时间</td><td>✓</td><td>奖品券码可核销的起始日期</td></tr><tr><td>核销结束时间</td><td>✓</td><td>奖品券码可核销的截止日期</td></tr><tr><td>库存</td><td>✓</td><td>奖品总库存数量</td></tr><tr><td>抽奖概率</td><td>✓</td><td>该奖品的中奖概率（数值）</td></tr><tr><td>显示顺序</td><td>✓</td><td>数字越小排序越靠前</td></tr><tr><td>商品主图</td><td>—</td><td>≤2MB，png/jpg/jpeg，建议尺寸 500×500</td></tr><tr><td>使用说明</td><td>—</td><td>富文本编辑器，填写奖品使用规则</td></tr></tbody></table><ol start="3"><li>确认后保存，可继续添加多个奖品</li></ol><h4 id="盲盒抽奖管理" tabindex="-1">盲盒抽奖管理 <a class="header-anchor" href="#盲盒抽奖管理" aria-label="Permalink to &quot;盲盒抽奖管理&quot;">​</a></h4><ul><li><strong>搜索筛选</strong>：支持按「小程序」「游戏名称」筛选，点击「重置」清空条件</li><li><strong>批量操作</strong>：勾选后可批量修改、删除</li><li><strong>单行操作</strong>： <ul><li><strong>修改</strong>：编辑活动信息</li><li><strong>删除</strong>：删除该活动</li><li><strong>商品配置</strong>：进入该活动的奖品配置页面</li><li><strong>生成链接</strong>：获取活动分享链接</li></ul></li></ul><hr><h2 id="订单中心" tabindex="-1">订单中心 <a class="header-anchor" href="#订单中心" aria-label="Permalink to &quot;订单中心&quot;">​</a></h2><h3 id="订单管理" tabindex="-1">订单管理 <a class="header-anchor" href="#订单管理" aria-label="Permalink to &quot;订单管理&quot;">​</a></h3><p>订单管理汇总全渠道（小程序、停车、活动等）产生的支付与兑换订单，支持多维检索、导出对账及单条退款操作。</p><h4 id="页面路径" tabindex="-1">页面路径 <a class="header-anchor" href="#页面路径" aria-label="Permalink to &quot;页面路径&quot;">​</a></h4><p>首页 / 订单中心 / 订单列表</p><h4 id="检索条件" tabindex="-1">检索条件 <a class="header-anchor" href="#检索条件" aria-label="Permalink to &quot;检索条件&quot;">​</a></h4><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>所属门店</td><td>下拉选择，支持按门店过滤</td></tr><tr><td>手机号</td><td>输入会员手机号，精确/模糊匹配</td></tr><tr><td>商品名称</td><td>输入商品/优惠券名称关键词</td></tr><tr><td>订单状态</td><td>下拉筛选：全部、已支付、待支付、已退款、已关闭等</td></tr><tr><td>创建时间</td><td>日期范围选择器，支持按下单时间区间过滤</td></tr></tbody></table><blockquote><p><strong>操作</strong>：点击「搜索」执行查询；点击「重置」清空所有条件；点击「导出」可将当前筛选结果导出为 Excel 对账文件。</p></blockquote><h4 id="列表字段-1" tabindex="-1">列表字段 <a class="header-anchor" href="#列表字段-1" aria-label="Permalink to &quot;列表字段&quot;">​</a></h4><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>商品名称</td><td>订单对应的商品或优惠券名称</td></tr><tr><td>门店名称</td><td>该笔订单归属的门店</td></tr><tr><td>商品数量</td><td>购买/兑换的数量</td></tr><tr><td>订单号</td><td>系统生成的唯一订单编号</td></tr><tr><td>金额</td><td>实付金额（元），纯积分兑换时显示为 0</td></tr><tr><td>积分</td><td>该笔订单涉及的积分变动</td></tr><tr><td>支付时间</td><td>用户完成支付的具体时间</td></tr><tr><td>订单状态</td><td>如：已支付、待支付、已退款、已关闭</td></tr><tr><td>电话</td><td>下单会员的联系电话</td></tr><tr><td>创建时间</td><td>订单生成时间</td></tr><tr><td>操作</td><td><strong>退款</strong>：对已支付订单发起原路退款（需确保账户资金充足）</td></tr></tbody></table><h4 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h4><ul><li>退款操作不可逆，请核对无误后再确认。</li><li>停车券的纯核销记录不在此列表，请前往「订单中心 → 核销明细」查看。</li><li>导出文件包含当前筛选条件下的全部数据，超大数据量时可能需要等待数秒。</li></ul><h3 id="核销明细" tabindex="-1">核销明细 <a class="header-anchor" href="#核销明细" aria-label="Permalink to &quot;核销明细&quot;">​</a></h3><p>核销明细用于记录所有优惠券、停车券、兑换商品等的核销流水，尤其适用于纯积分兑换的停车券等无需支付金额的券类核销追踪。</p><h4 id="页面路径-1" tabindex="-1">页面路径 <a class="header-anchor" href="#页面路径-1" aria-label="Permalink to &quot;页面路径&quot;">​</a></h4><p>首页 / 订单中心 / 核销明细</p><h4 id="检索条件-1" tabindex="-1">检索条件 <a class="header-anchor" href="#检索条件-1" aria-label="Permalink to &quot;检索条件&quot;">​</a></h4><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>归属商户</td><td>下拉选择，按核销发生门店/商户过滤</td></tr><tr><td>会员手机</td><td>输入会员手机号</td></tr><tr><td>商品名称</td><td>输入商品或券名称关键词</td></tr><tr><td>核销编号</td><td>输入系统核销流水号，精确查询</td></tr><tr><td>核销状态</td><td>下拉筛选：已核销、未核销、已撤销等</td></tr><tr><td>核销人</td><td>下拉选择，按操作员过滤</td></tr><tr><td>核销时间</td><td>日期范围，按实际核销操作时间过滤</td></tr><tr><td>发券时间</td><td>日期范围，按券发放时间过滤</td></tr><tr><td>商品券券号</td><td>输入具体券号，精确查询单张券的核销记录</td></tr></tbody></table><blockquote><p><strong>操作</strong>：点击「搜索」执行查询；点击「重置」清空条件；点击「导出」可导出核销对账报表。</p></blockquote><h4 id="列表字段-2" tabindex="-1">列表字段 <a class="header-anchor" href="#列表字段-2" aria-label="Permalink to &quot;列表字段&quot;">​</a></h4><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>订单号</td><td>对应原始订单编号（停车券场景下可能显示车牌号）</td></tr><tr><td>发券时间</td><td>优惠券/券发放至会员账户的时间</td></tr><tr><td>核销券号</td><td>系统生成的唯一核销流水号</td></tr><tr><td>商品名称</td><td>被核销的商品或券名称</td></tr><tr><td>商品数量</td><td>核销数量</td></tr><tr><td>会员电话</td><td>持有并核销该券的会员手机号</td></tr><tr><td>核销状态</td><td>如：已核销（绿色标签）、未核销、已撤销</td></tr><tr><td>核销时间</td><td>实际执行核销操作的时间</td></tr><tr><td>核销人</td><td>执行核销操作的后台账号或门店操作员</td></tr><tr><td>归属部门</td><td>该笔核销归属的门店/部门</td></tr><tr><td>操作</td><td>视权限可能支持撤销核销等操作</td></tr></tbody></table><h4 id="常见场景" tabindex="-1">常见场景 <a class="header-anchor" href="#常见场景" aria-label="Permalink to &quot;常见场景&quot;">​</a></h4><ul><li><strong>停车券核销</strong>：会员在小程序兑换停车券后，离场时系统自动或管理员手动核销，流水在此记录。订单号列可能显示车牌号（如 <code>渝A365CA</code>）或系统订单号（如 <code>tc_xxx</code>）。</li><li><strong>商品券核销</strong>：会员到店出示券码，店员扫码或后台输入券号完成核销。</li><li><strong>对账导出</strong>：财务可按「核销时间」或「发券时间」导出指定区间的明细，与第三方停车系统或门店收银进行核对。</li></ul><blockquote><p><strong>权限说明</strong>：「核销明细」为项目级/平台级视角，管理员可查看所有门店的核销数据；门店账号登录后请查看「商家核销明细」。</p></blockquote><h3 id="商家核销明细" tabindex="-1">商家核销明细 <a class="header-anchor" href="#商家核销明细" aria-label="Permalink to &quot;商家核销明细&quot;">​</a></h3><p>商家核销明细是<strong>门店账号</strong>登录后看到的核销数据视图，数据范围自动限定为当前登录门店，搜索条件更精简，便于门店操作员快速核对本店券码核销情况。</p><h4 id="页面路径-2" tabindex="-1">页面路径 <a class="header-anchor" href="#页面路径-2" aria-label="Permalink to &quot;页面路径&quot;">​</a></h4><p>首页 / 订单中心 / 商家核销明细</p><h4 id="检索条件-2" tabindex="-1">检索条件 <a class="header-anchor" href="#检索条件-2" aria-label="Permalink to &quot;检索条件&quot;">​</a></h4><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>会员手机</td><td>输入会员手机号，查询该会员在本店的核销记录</td></tr><tr><td>商品券号</td><td>输入具体券号，查询单张券的核销状态</td></tr></tbody></table><blockquote><p><strong>操作</strong>：点击「搜索」执行查询；点击「重置」清空条件。</p></blockquote><h4 id="列表字段-3" tabindex="-1">列表字段 <a class="header-anchor" href="#列表字段-3" aria-label="Permalink to &quot;列表字段&quot;">​</a></h4><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>订单号</td><td>对应原始订单编号</td></tr><tr><td>发券时间</td><td>优惠券/券发放至会员账户的时间</td></tr><tr><td>核销券号</td><td>系统生成的唯一核销流水号</td></tr><tr><td>商品名称</td><td>被核销的商品或券名称</td></tr><tr><td>商品数量</td><td>核销数量</td></tr><tr><td>会员电话</td><td>持有并核销该券的会员手机号</td></tr><tr><td>核销状态</td><td>如：已核销（绿色标签）、未核销</td></tr><tr><td>核销时间</td><td>实际执行核销操作的时间</td></tr></tbody></table><h4 id="与「核销明细」的区别" tabindex="-1">与「核销明细」的区别 <a class="header-anchor" href="#与「核销明细」的区别" aria-label="Permalink to &quot;与「核销明细」的区别&quot;">​</a></h4><table tabindex="0"><thead><tr><th>对比项</th><th>核销明细（平台级）</th><th>商家核销明细（门店级）</th></tr></thead><tbody><tr><td>可见角色</td><td>项目管理员/运营</td><td>门店账号/店员</td></tr><tr><td>数据范围</td><td>全部门店</td><td>仅当前登录门店</td></tr><tr><td>检索条件</td><td>9 项（含归属商户、核销人、时间区间等）</td><td>2 项（会员手机、商品券号）</td></tr><tr><td>列表字段</td><td>含核销人、归属部门</td><td>精简字段，无归属部门</td></tr><tr><td>导出功能</td><td>支持导出</td><td>一般不支持</td></tr></tbody></table><h3 id="支付积分订单" tabindex="-1">支付积分订单 <a class="header-anchor" href="#支付积分订单" aria-label="Permalink to &quot;支付积分订单&quot;">​</a></h3><p>支付积分订单记录会员在线下门店通过微信支付消费后，系统根据「支付即积分」规则自动返还积分的流水。该功能需先完成微信支付商户号打通及积分规则配置。</p><h4 id="页面路径-3" tabindex="-1">页面路径 <a class="header-anchor" href="#页面路径-3" aria-label="Permalink to &quot;页面路径&quot;">​</a></h4><p>首页 / 订单中心 / 支付积分订单</p><h4 id="检索条件-3" tabindex="-1">检索条件 <a class="header-anchor" href="#检索条件-3" aria-label="Permalink to &quot;检索条件&quot;">​</a></h4><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>所属门店</td><td>下拉选择，按消费门店过滤</td></tr><tr><td>手机号</td><td>输入会员手机号</td></tr><tr><td>业态</td><td>下拉选择，按门店业态类型过滤</td></tr><tr><td>支付方式</td><td>下拉筛选：微信支付、支付宝等</td></tr><tr><td>支付时间</td><td>日期范围，按交易完成时间过滤</td></tr></tbody></table><blockquote><p><strong>操作</strong>：点击「搜索」执行查询；点击「重置」清空条件；点击「导出」可导出对账及积分发放报表。</p></blockquote><h4 id="列表字段-4" tabindex="-1">列表字段 <a class="header-anchor" href="#列表字段-4" aria-label="Permalink to &quot;列表字段&quot;">​</a></h4><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>商圈名称</td><td>交易所属的商圈/购物中心</td></tr><tr><td>门店名称</td><td>具体消费的门店</td></tr><tr><td>交易完成时间</td><td>用户支付成功的时间</td></tr><tr><td>金额</td><td>实际支付金额（元）</td></tr><tr><td>积分数</td><td>根据「支付即积分」规则自动计算的返还积分</td></tr><tr><td>支付方式</td><td>如：微信支付、支付宝</td></tr><tr><td>交易订单号</td><td>第三方支付平台的交易流水号（如微信商户订单号 <code>4200003...</code>）</td></tr><tr><td>用户昵称</td><td>会员在小程序中的昵称</td></tr><tr><td>电话</td><td>会员绑定的手机号</td></tr><tr><td>退款标记</td><td><code>N</code> 表示未退款；若订单发生退款，积分通常会同步扣回</td></tr></tbody></table><h4 id="积分计算规则" tabindex="-1">积分计算规则 <a class="header-anchor" href="#积分计算规则" aria-label="Permalink to &quot;积分计算规则&quot;">​</a></h4><ul><li>不同业态/门店可配置不同的积分返还比例（如 1 元 = 1 积分、1 元 = 0.5 积分等）。</li><li>积分通常在支付成功后实时到账，延迟不超过 5 分钟。</li><li>若用户发起退款，系统会自动扣回对应积分，退款标记将同步更新。</li></ul><h4 id="注意事项-1" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项-1" aria-label="Permalink to &quot;注意事项&quot;">​</a></h4><ul><li>该列表仅展示通过「支付即积分」功能产生的积分流水，不包含签到、活动奖励等其他积分来源。</li><li>如需查看会员全部积分变动，请前往「会员中心 → 会员列表 → 积分明细」。</li><li>交易订单号可与微信支付商户后台流水进行交叉对账。</li></ul><h3 id="异常积分管理" tabindex="-1">异常积分管理 <a class="header-anchor" href="#异常积分管理" aria-label="Permalink to &quot;异常积分管理&quot;">​</a></h3><p>异常积分管理用于识别并处理会员在「支付即积分」场景下的异常消费行为，防止刷单套利，保障积分体系健康。</p><h4 id="页面路径-4" tabindex="-1">页面路径 <a class="header-anchor" href="#页面路径-4" aria-label="Permalink to &quot;页面路径&quot;">​</a></h4><p>首页 / 订单中心 / 异常积分管理</p><h4 id="异常积分规则" tabindex="-1">异常积分规则 <a class="header-anchor" href="#异常积分规则" aria-label="Permalink to &quot;异常积分规则&quot;">​</a></h4><blockquote><p><strong>规则说明</strong>：以自然月为统计单位，同一会员在同一柜台/门店 <strong>30 天内消费 &gt; 7 次</strong> 即触发积分异常。该阈值兼顾正常高频消费与恶意刷单场景，可根据业务需求联系技术调整。</p></blockquote><h4 id="检索条件-4" tabindex="-1">检索条件 <a class="header-anchor" href="#检索条件-4" aria-label="Permalink to &quot;检索条件&quot;">​</a></h4><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>日期</td><td>月份选择器（如 <code>2026-01</code>），按自然月统计异常数据</td></tr></tbody></table><blockquote><p><strong>操作</strong>：选择月份后点击「搜索」；点击「重置」恢复默认；点击「导出」可导出当月异常会员清单。</p></blockquote><h4 id="列表字段-5" tabindex="-1">列表字段 <a class="header-anchor" href="#列表字段-5" aria-label="Permalink to &quot;列表字段&quot;">​</a></h4><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>昵称</td><td>会员在小程序中的昵称</td></tr><tr><td>手机号</td><td>会员绑定的手机号</td></tr><tr><td>消费次数</td><td>该会员在统计周期内的消费笔数</td></tr><tr><td>积分数</td><td>该会员在统计周期内获得的积分总额</td></tr><tr><td>操作</td><td><strong>点击查看</strong>：查看该会员的详细消费流水；<strong>积分处理</strong>：手动扣减或补发积分</td></tr></tbody></table><h4 id="积分处理" tabindex="-1">积分处理 <a class="header-anchor" href="#积分处理" aria-label="Permalink to &quot;积分处理&quot;">​</a></h4><p>点击「积分处理」后弹出处理窗口：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>剩余积分</td><td>该会员当前账户剩余积分（只读）</td></tr><tr><td>积分处理</td><td>输入调整数值：正数为补发积分，负数为扣减积分（如 <code>-15</code>）</td></tr><tr><td>积分描述</td><td>填写调整原因，便于后续审计追溯</td></tr><tr><td>所属商户</td><td>下拉选择积分变动归属的门店/商户（必填）</td></tr></tbody></table><blockquote><p><strong>操作</strong>：填写完成后点击「确定」提交；点击「取消」关闭窗口。积分调整将实时同步至会员账户并在「积分明细」中留痕。</p></blockquote><h4 id="注意事项-2" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项-2" aria-label="Permalink to &quot;注意事项&quot;">​</a></h4><ul><li>异常积分管理仅针对「支付即积分」产生的积分，不包含签到、活动奖励等其他来源。</li><li>积分扣减操作不可逆，请核实消费流水后再处理。</li><li>建议定期（如每月初）导出上月异常数据，复盘并优化积分规则或阈值。</li></ul><hr><h2 id="公域管理" tabindex="-1">公域管理 <a class="header-anchor" href="#公域管理" aria-label="Permalink to &quot;公域管理&quot;">​</a></h2><h3 id="抖音核销订单" tabindex="-1">抖音核销订单 <a class="header-anchor" href="#抖音核销订单" aria-label="Permalink to &quot;抖音核销订单&quot;">​</a></h3><p>抖音核销订单用于同步并管理抖音团购（POI 代金券/套餐）在门店的核销流水，实现公域流量到私域的订单闭环追踪。</p><h4 id="页面路径-5" tabindex="-1">页面路径 <a class="header-anchor" href="#页面路径-5" aria-label="Permalink to &quot;页面路径&quot;">​</a></h4><p>首页 / 公域管理 / 抖音核销订单</p><h4 id="检索条件-5" tabindex="-1">检索条件 <a class="header-anchor" href="#检索条件-5" aria-label="Permalink to &quot;检索条件&quot;">​</a></h4><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>归属商户</td><td>下拉选择，按核销门店过滤</td></tr><tr><td>核销人</td><td>下拉选择，按操作员/门店账号过滤</td></tr><tr><td>核销时间</td><td>日期范围，按实际核销操作时间过滤</td></tr></tbody></table><blockquote><p><strong>操作</strong>：点击「搜索」执行查询；点击「重置」清空条件。</p></blockquote><h4 id="列表字段-6" tabindex="-1">列表字段 <a class="header-anchor" href="#列表字段-6" aria-label="Permalink to &quot;列表字段&quot;">​</a></h4><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>订单号</td><td>抖音平台生成的唯一订单编号（如 <code>10938...</code>）</td></tr><tr><td>商品名称</td><td>团购商品名称，含门店及使用规则说明（如 <code>50元代金券｜【饭团匠·IMC国际广场】全场通用可叠3张</code>）</td></tr><tr><td>商品数量</td><td>核销的团购券张数/份数</td></tr><tr><td>商品单价</td><td>单张团购券的售价（元）</td></tr><tr><td>核销门店</td><td>实际执行核销的门店名称</td></tr><tr><td>核销人</td><td>执行核销操作的后台账号</td></tr><tr><td>核销时间</td><td>实际核销的日期</td></tr></tbody></table><h4 id="常见场景-1" tabindex="-1">常见场景 <a class="header-anchor" href="#常见场景-1" aria-label="Permalink to &quot;常见场景&quot;">​</a></h4><ul><li><strong>代金券核销</strong>：会员在抖音购买「50元代金券」后到店消费，店员在后台或小程序端输入核销码完成核销，流水自动同步至此列表。</li><li><strong>多店连锁</strong>：不同门店的核销数据自动归属到对应商户，便于总部统一对账。</li><li><strong>对账核对</strong>：财务可按「核销时间」区间导出数据，与抖音来客后台的核销报表进行交叉核对。</li></ul><h4 id="注意事项-3" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项-3" aria-label="Permalink to &quot;注意事项&quot;">​</a></h4><ul><li>该列表仅展示已在系统中完成核销的抖音订单，未核销的团购券请在「抖音来客」后台查看。</li><li>如需支持抖音团购商品的上架或退款，需前往「抖音来客」官方后台操作，本系统仅做核销记录同步。</li><li>若某笔订单未同步，请检查门店抖音来客账号的授权绑定状态。</li></ul><hr><h2 id="智慧营销" tabindex="-1">智慧营销 <a class="header-anchor" href="#智慧营销" aria-label="Permalink to &quot;智慧营销&quot;">​</a></h2><h3 id="精准发券" tabindex="-1">精准发券 <a class="header-anchor" href="#精准发券" aria-label="Permalink to &quot;精准发券&quot;">​</a></h3><p>精准发券支持向指定会员群体定向发放优惠券，适用于节日营销、会员唤醒、补偿安抚等场景。支持直接发券与批量导入发券两种模式。</p><h4 id="页面路径-6" tabindex="-1">页面路径 <a class="header-anchor" href="#页面路径-6" aria-label="Permalink to &quot;页面路径&quot;">​</a></h4><p>首页 / 智慧营销 / 精准发券</p><h4 id="直接发券" tabindex="-1">直接发券 <a class="header-anchor" href="#直接发券" aria-label="Permalink to &quot;直接发券&quot;">​</a></h4><p>在页面上方输入发券信息，查询目标人群后一键发放：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>备注</td><td>填写本次发券活动的备注说明，便于后续追溯</td></tr><tr><td>券号</td><td>输入要发放的商品/优惠券编号</td></tr><tr><td>发券数量</td><td>输入每位会员发放的张数</td></tr></tbody></table><blockquote><p><strong>操作</strong>：填写券号和发券数量后，点击「查询人数」可预览符合条件的会员数量；确认无误后点击「一键发券」执行发放。</p></blockquote><h4 id="批量导入发券" tabindex="-1">批量导入发券 <a class="header-anchor" href="#批量导入发券" aria-label="Permalink to &quot;批量导入发券&quot;">​</a></h4><p>针对大批量、特定名单的定向发券需求，可通过 Excel 模板导入会员列表后批量发放：</p><ol><li>点击「导入发券」按钮，弹出上传窗口。</li><li>点击「下载模板」获取标准 Excel 模板，按模板格式填写会员信息（通常包含手机号、券号、数量等字段）。</li><li>将填好的文件拖拽至上传区域，或点击上传选择文件（仅支持 <code>xls</code>、<code>xlsx</code> 格式）。</li><li>点击「确定」完成导入，系统将按表格内容逐条发券。</li></ol><h4 id="列表字段-7" tabindex="-1">列表字段 <a class="header-anchor" href="#列表字段-7" aria-label="Permalink to &quot;列表字段&quot;">​</a></h4><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>微信昵称</td><td>会员在小程序中的昵称</td></tr><tr><td>手机号</td><td>会员绑定的手机号</td></tr><tr><td>积分</td><td>会员当前积分余额</td></tr><tr><td>会员标签</td><td>该会员被打上的标签（如「高价值用户」「沉睡用户」）</td></tr><tr><td>备注</td><td>发券时填写的备注信息</td></tr></tbody></table><h4 id="注意事项-4" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项-4" aria-label="Permalink to &quot;注意事项&quot;">​</a></h4><ul><li>精准发券仅支持发放普通优惠券，不支持停车券。</li><li>批量导入前请务必下载最新模板，避免字段格式不符导致导入失败。</li><li>发券操作通常不可逆，请核对券号及数量后再确认发放。</li><li>发券后会员将实时在小程序「券包」中收到该优惠券。</li></ul><hr><h2 id="bi商业分析" tabindex="-1">BI商业分析 <a class="header-anchor" href="#bi商业分析" aria-label="Permalink to &quot;BI商业分析&quot;">​</a></h2><h3 id="会员数据分析-标准版" tabindex="-1">会员数据分析（标准版） <a class="header-anchor" href="#会员数据分析-标准版" aria-label="Permalink to &quot;会员数据分析（标准版）&quot;">​</a></h3><p>会员数据分析提供多维度的会员画像与消费行为看板，帮助运营团队洞察会员价值、识别沉睡用户、制定差异化营销策略。</p><h4 id="页面路径-7" tabindex="-1">页面路径 <a class="header-anchor" href="#页面路径-7" aria-label="Permalink to &quot;页面路径&quot;">​</a></h4><p>首页 / BI商业分析 / 会员数据分析（标准版）</p><h4 id="看板模块" tabindex="-1">看板模块 <a class="header-anchor" href="#看板模块" aria-label="Permalink to &quot;看板模块&quot;">​</a></h4><p><strong>1. 会员消费（积分）数据分层</strong></p><p>以漏斗图展示会员的消费活跃度分层，支持按「总会员数」等维度筛选：</p><table tabindex="0"><thead><tr><th>层级</th><th>说明</th></tr></thead><tbody><tr><td>总会员数</td><td>系统注册会员总量</td></tr><tr><td>近一个月未消费</td><td>最近 30 天内无消费记录的会员数</td></tr><tr><td>近三个月未消费</td><td>最近 90 天内无消费记录的会员数</td></tr><tr><td>近半年未消费</td><td>最近 180 天内无消费记录的会员数</td></tr></tbody></table><blockquote><p>通过该漏斗可快速识别流失风险：漏斗越宽，说明短期沉睡会员占比越大，需及时触发唤醒营销。</p></blockquote><p><strong>2. 会员消费频次分析</strong></p><p>以金字塔图将会员按年消费频次划分为四类，点击「下载」可导出对应人群列表：</p><table tabindex="0"><thead><tr><th>会员类型</th><th>定义</th><th>用途</th></tr></thead><tbody><tr><td>忠诚会员</td><td>一年消费 <strong>30 ~ 100</strong> 次</td><td>核心高价值用户，适合专属权益、裂变激励</td></tr><tr><td>高粘性会员</td><td>一年消费 <strong>15 ~ 29</strong> 次</td><td>活跃主力，适合推新品、组合套餐</td></tr><tr><td>摇摆会员</td><td>消费频次介于沉睡与活跃之间</td><td>易流失群体，适合限时优惠券召回</td></tr><tr><td>沉睡会员</td><td>长期无消费</td><td>需强利益点（大额券、积分翻倍）唤醒</td></tr></tbody></table><p><strong>3. 会员授权类型分布</strong></p><p>环形图展示会员授权状态：</p><table tabindex="0"><thead><tr><th>指标</th><th>说明</th></tr></thead><tbody><tr><td>总会员数</td><td>系统注册会员总量</td></tr><tr><td>快速积分授权数</td><td>已授权「支付即积分」自动积分功能的会员数</td></tr></tbody></table><blockquote><p>点击「下载未快速授权用户」可导出尚未开通支付即积分的会员名单，便于定向引导授权。</p></blockquote><p><strong>4. 拥有爱车的会员</strong></p><p>展示已绑定车牌的会员占比（如 <strong>71.0%</strong>），反映停车场景的用户渗透率。</p><blockquote><p>点击「下载」可导出已绑定车牌的会员清单，便于结合停车优惠券做精准营销。</p></blockquote><h4 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to &quot;使用建议&quot;">​</a></h4><ul><li><strong>定期复盘</strong>：建议每月初查看「会员消费频次分析」，及时调整当月会员运营重点。</li><li><strong>分层运营</strong>：将「下载」的人群包导入「智慧营销 → 精准发券」，实现千人千面的券投放。</li><li><strong>流失预警</strong>：关注「近一个月未消费」人数环比变化，若连续两月上升，需检查商品券吸引力或推送触达率。</li></ul><hr><h2 id="门店核销" tabindex="-1">门店核销 <a class="header-anchor" href="#门店核销" aria-label="Permalink to &quot;门店核销&quot;">​</a></h2><h3 id="核销操作流程" tabindex="-1">核销操作流程 <a class="header-anchor" href="#核销操作流程" aria-label="Permalink to &quot;核销操作流程&quot;">​</a></h3><p>门店核销员可通过小程序端完成优惠券的扫码核销，无需登录电脑后台。</p><h4 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h4><p><strong>一、进入小程序个人中心</strong></p><p>会员或核销员打开小程序，点击底部「我的」进入个人中心页面。</p><p><strong>二、点击商家管理</strong></p><p>在个人中心菜单列表中，找到并点击「<strong>商家管理</strong>」入口。</p><p><strong>三、门店核销员登录</strong></p><p>进入「商户登陆」页面，输入门店后台分配的<strong>账号</strong>和<strong>密码</strong>，点击「登陆」。</p><blockquote><p><strong>说明</strong>：该账号由项目管理员在「商户管理 → 账号管理」中创建，一门店可配置多个核销账号。</p></blockquote><p><strong>四、扫码核销</strong></p><p>登录成功后进入「商户管理」页面：</p><ol><li>点击「<strong>+扫码核销优惠券</strong>」按钮，唤起摄像头扫描会员出示的券码。</li><li>扫码成功后系统自动核销，会员小程序中的该券状态同步变为「已使用」。</li></ol><p><strong>五、查看记录与统计</strong></p><p>页面下方提供三个 Tab 切换：</p><table tabindex="0"><thead><tr><th>Tab</th><th>说明</th></tr></thead><tbody><tr><td>优惠券核销记录</td><td>查看本门店所有已核销的优惠券流水</td></tr><tr><td>交易记录</td><td>查看与本门店相关的交易订单</td></tr><tr><td>核销统计</td><td>按时间段统计核销笔数、金额等汇总数据</td></tr></tbody></table><h4 id="注意事项-5" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项-5" aria-label="Permalink to &quot;注意事项&quot;">​</a></h4><ul><li>核销操作即时生效，请确认券码无误后再扫码。</li><li>若账号无法登录，请联系项目管理员检查账号状态及密码是否正确。</li><li>纯停车券的核销请使用对应停车系统的管理后台，不在此小程序核销范围内。</li></ul><hr><h2 id="圈店流程" tabindex="-1">圈店流程 <a class="header-anchor" href="#圈店流程" aria-label="Permalink to &quot;圈店流程&quot;">​</a></h2><p>圈店流程用于将线下门店纳入微信/支付宝商圈体系，打通支付数据回传通道，实现会员消费自动积分。整个流程由技术服务商协助完成，商户仅需配合提供必要资料。</p><h3 id="申请官方账号及商圈能力权限" tabindex="-1">申请官方账号及商圈能力权限 <a class="header-anchor" href="#申请官方账号及商圈能力权限" aria-label="Permalink to &quot;申请官方账号及商圈能力权限&quot;">​</a></h3><p>以商管主体申请微信支付官方账号和支付宝企业账号（可由技术服务商代申请），后续由技术服务公司代为申请商圈官方能力接口。</p><table tabindex="0"><thead><tr><th>平台</th><th>说明</th></tr></thead><tbody><tr><td>微信侧</td><td>申请微信支付商户号及商圈能力接口权限</td></tr><tr><td>支付宝侧</td><td>申请支付宝企业账号及商圈相关能力接口</td></tr></tbody></table><h3 id="门店圈入方式" tabindex="-1">门店圈入方式 <a class="header-anchor" href="#门店圈入方式" aria-label="Permalink to &quot;门店圈入方式&quot;">​</a></h3><p>门店需完成以下三种方式中的至少一种，方可被纳入商圈支付数据抓取范围：</p><ol><li><strong>现场支付抓取</strong><ul><li><strong>微信</strong>：需在门店现场完成一笔真实支付，以验证支付通道归属。</li><li><strong>支付宝</strong>：无需现场支付，可直接通过后台配置完成圈入。</li></ul></li><li><strong>录入已有的订单号</strong><ul><li>提供该门店近期已完成的支付订单号，由技术方在后台录入匹配。</li></ul></li><li><strong>门店支付通道的商户号</strong><ul><li>直接提供门店当前使用的微信支付商户号或支付宝商户号，进行绑定。</li></ul></li></ol><h3 id="录入门店信息及门店编号" tabindex="-1">录入门店信息及门店编号 <a class="header-anchor" href="#录入门店信息及门店编号" aria-label="Permalink to &quot;录入门店信息及门店编号&quot;">​</a></h3><p>在系统后台录入门店基础信息，确保与微信/支付宝商圈平台的门店数据一一对应：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>门店名称</td><td>与营业执照及支付商户号一致的门店名称</td></tr><tr><td>所属业态</td><td>选择该门店对应的业态分类</td></tr><tr><td>门店编号</td><td>由技术服务商在系统后台自动生成，再录入微信/支付宝商圈平台进行编号匹配</td></tr></tbody></table><blockquote><p><strong>注意</strong>：门店编号必须保持两端（本系统后台与微信/支付宝商圈平台）一致，否则支付数据无法正确回传。</p></blockquote><h3 id="现场测试" tabindex="-1">现场测试 <a class="header-anchor" href="#现场测试" aria-label="Permalink to &quot;现场测试&quot;">​</a></h3><p>录入相关门店信息后，进入现场测试环节：</p><ol><li>测试人员注册成为小程序会员。</li><li>在门店现场进行真实消费支付。</li><li>验证支付数据是否成功回传至系统，会员是否自动获得对应积分。</li><li>若测试失败，检查门店编号、商户号、支付通道配置是否一致。</li></ol><h3 id="商家须知-供购物中心门店宣导使用" tabindex="-1">商家须知（供购物中心门店宣导使用） <a class="header-anchor" href="#商家须知-供购物中心门店宣导使用" aria-label="Permalink to &quot;商家须知（供购物中心门店宣导使用）&quot;">​</a></h3><p>为保障会员积分体系正常运转，请各合作商家配合以下事项：</p><ol><li><strong>宣导入会流程</strong>：配合商场管理方，积极宣导本项目的会员入会流程，并在店内适当位置张贴相关物料。</li><li><strong>收单渠道变更报备</strong>：商家在经营过程中，如因自身发展需要更换移动支付收单渠道（如更换支付服务商、变更商户号等），<strong>须提前告知商场管理方</strong>，由技术公司安排人员重新录入门店收单信息。</li><li><strong>消费积分异常反馈</strong>：如消费者正常消费后无法自动积分，请积极引导消费者联系管理方，由相关技术团队验证后及时处理，保障消费者合法会员权益。</li></ol><hr><p><em>文档持续更新中，如有疑问请联系技术支持。</em></p>',488)])])}const c=d(o,[["render",e]]);export{u as __pageData,c as default};
